"use client"

import React, { type ComponentType } from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { HighlightCard } from "@/components/blocks/cards/HighlightCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { SeeMoreLink } from "@/components/blocks/navigation/SeeMoreLink"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { type CallerIdentity } from "@/components/frames/_identity"

/**
 * Shape of a {@link ContinueCard} ΓÇö derived from what the surface IS, not from
 * individual style flags.
 *
 * - `"item"` ΓÇö one of N resume cards in a grid/list. The card is a static frame;
 *   the CTA is a real {@link SeeMoreLink} ("Continue ΓåÆ") on its own row ΓÇö hover
 *   and click live on that link only (same as LabeledCard "See more"). It carries
 *   NO leading icon (a compact CTA tile reads off its title + "Continue ΓåÆ"; a
 *   decorative badge is just clutter) and no accent ring (N accented cards means
 *   none of them stands out).
 * - `"hero"` ΓÇö the single standout "you left this in progress" card on a
 *   surface. The CTA is a real chip button on its own row, `icon` sinks behind
 *   the content as a watermark, and the card gets an accent ring.
 */
export type ContinueCardVariant = "item" | "hero"

/**
 * Props for the {@link ContinueCard} block.
 *
 * A presentational, props-only card that surfaces a single "continue where you
 * left off" item. All interactivity is delivered by the caller via
 * {@link onPress} or {@link href}; the block fetches nothing and reads no
 * global store.
 *
 * Does NOT take `className` (BLOCK-4 ΓÇö a block hands out no escape hatch; a
 * caller that needs a specific placement wraps this card in a frame instead,
 * the same treatment `StatusChip` already carries). `ResumeCard`
 * (`@/components/pages/DashboardPage/ContinueLearning/ResumeCard`) still
 * forwards its own `className` straight into this card ΓÇö that call site needs
 * a follow-up fix; it sits outside this folder so it isn't touched here.
 */
export interface ContinueCardProps {
    /**
     * What this card IS on its surface ΓÇö see {@link ContinueCardVariant}.
     * Required: it decides icon placement, CTA affordance, and accent together,
     * so a surface cannot end up with an arbitrary mix of the three.
     */
    variant: ContinueCardVariant
    /**
     * Primary label of the item being continued (course / module / lesson
     * title). Rendered via {@link Typography} weight="medium", truncated to one
     * line.
     */
    title: string
    /**
     * Optional secondary label under the title ΓÇö e.g. module name, lesson
     * number, or position in a session. Truncated to one line.
     */
    subtitle?: string
    /**
     * Current progress. The {@link ProgressMeter} renders if and only if this is
     * provided ΓÇö pass it only when real progress data exists. Omit it rather
     * than passing a placeholder to satisfy the type.
     */
    value?: number
    /** Maximum value representing 100 % completion. Defaults to `100`. */
    max?: number
    /**
     * Optional call-to-action label (e.g. "Continue"). Rendered ΓÇö on its OWN
     * row below the title/subtitle ΓÇö as a real {@link SeeMoreLink} for
     * `variant="item"` (press + hover on the link only, same as LabeledCard
     * "See more"), and as a chip button for `variant="hero"`.
     */
    ctaLabel?: string
    /**
     * Optional semantic momentum cue (e.g. `FireIcon` for a daily streak,
     * `ClockCounterClockwiseIcon` for a session left mid-flight). Rendered ONLY
     * for `variant="hero"`, where it sinks behind the content as a watermark;
     * `variant="item"` shows no leading icon, so passing one there is a no-op.
     * Decorative for a11y ΓÇö {@link title} carries the accessible name. Omit when
     * the item has no such concept; never add one for visual symmetry alone.
     */
    icon?: ComponentType
    /**
     * Renders `subtitle` in warning tone instead of muted ΓÇö only for a REAL
     * time-sensitive fact already present in the subtitle text (e.g. a
     * server-enforced deadline). Never fabricate a countdown to trigger this.
     */
    urgent?: boolean
    /**
     * Optional press handler. For `variant="item"` it wires to the
     * {@link SeeMoreLink} CTA; for `variant="hero"` it wires to the CTA chip.
     * Prefer {@link href} for pure navigation.
     */
    onPress?: () => void
    /** Optional destination URL. Takes priority over {@link onPress}. */
    href?: string
    /**
     * Caller identity to wear on this card's root element instead of its own ΓÇö pass this
     * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its
     * own) is using this card AS its root element, instead of wrapping it in a raw `<div
     * data-tier=ΓÇª data-component=ΓÇª>`. See `_identity.ts`. Forwarded to whichever element this
     * card actually draws as its outer shape ΓÇö the underlying `SectionCard`, or the `Box` that
     * wraps it when `hero`'s watermark needs a clipped positioning context ΓÇö never both, so the
     * pair lands on exactly one element. Omitted ΓåÆ that element keeps emitting its own identity,
     * unchanged.
     */
    identity?: CallerIdentity
}

/**
 * ContinueCard renders a "pick up where you left off" surface inside a
 * {@link SectionCard} frame: an info row (title + subtitle), then a CTA
 * row (both variants render `ctaLabel` here, never inline with the title ΓÇö
 * see {@link ContinueCardProps.ctaLabel}), then a {@link ProgressMeter} when
 * {@link ContinueCardProps.value} is provided.
 *
 * @param props - {@link ContinueCardProps}
 * @see Story: .storybook/stories/blocks/cards/ContinueCard/ContinueCard.stories
 */
export const ContinueCard = ({
    variant,
    title,
    subtitle,
    value,
    max = 100,
    ctaLabel,
    icon: Icon,
    urgent = false,
    onPress,
    href,
    identity,
}: ContinueCardProps) => {
    const isHero = variant === "hero"
    // A watermark icon needs (a) a positioning context sized to the card's own
    // footprint, (b) that same footprint to CLIP it at the rounded corners, and
    // (c) its siblings pulled into the same paint layer so they render above it
    // instead of under it. `SectionCard` exposes none of that (missingVocabulary:
    // no overlay/decoration slot, no relative/overflow control on the leaf) ΓÇö
    // only `hero` with a real `icon` needs any of it, `item` never renders one.
    const hasWatermark = isHero && Boolean(Icon)

    // Item CTA is a real SeeMoreLink (own hover + click). Never wrap the card ΓÇö
    // that would nest interactive controls and steal hover from the link.
    // Hero CTA is also its own control, so the card stays a static frame too.
    const ctaNode = ctaLabel
        ? isHero
            ? href
                ? (
                    // missingVocabulary: no atom/leaf renders a filled, pill-shaped
                    // NAVIGATIONAL link ΓÇö the `Button` atom only takes `onPress`
                    // (no `href`), and `SeeMoreLink`/`Link.LinkSeeMore` render plain
                    // accent text, not a filled chip. Minimal local anchor kept for
                    // this one named-but-unsupported shape.
                    <a
                        href={href}
                        className="inline-flex w-fit shrink-0 items-center gap-2 whitespace-nowrap rounded-3xl bg-accent px-4 py-2 text-sm font-medium text-accent-foreground no-underline"
                    >
                        {ctaLabel}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-3.5" />
                    </a>
                )
                : (
                    <Button
                        variant="primary"
                        size="sm"
                        label={ctaLabel}
                        suffixIcon={ArrowRightIcon}
                        onPress={onPress}
                    />
                )
            : (
                <SeeMoreLink href={href} onPress={onPress}>
                    {ctaLabel}
                </SeeMoreLink>
            )
        : null

    const titleStack = (
        <StackV
            gap={3}
            classNames={["min-w-0"]}
            items={[
                () => <Typography weight="medium" truncate text={title} />,
                ...(subtitle
                    ? [
                        () => (
                            // missingVocabulary: `Typography`'s `color` union has
                            // `accent-soft`/`success-soft` but no `warning-soft` ΓÇö
                            // `urgent` previously read `text-warning-soft-foreground`
                            // via `className`. Nearest atom-supported token used
                            // instead of reopening the hatch.
                            <Typography size="xs" color={urgent ? "warning" : "muted"} truncate text={subtitle} />
                        ),
                    ]
                    : []),
            ]}
        />
    )

    // Identity lands on exactly ONE element ΓÇö whichever this card actually draws as its
    // outer shape. `hasWatermark` ΓåÆ the `Box` below is that element (it needs the clip/
    // positioning context anyway), so `SectionCard` keeps ITS OWN identity nested inside
    // instead of doubling the caller's pair onto two elements. Otherwise `SectionCard` IS
    // that element, so it takes the caller's identity directly.
    const sectionCard = (
        <SectionCard identity={hasWatermark ? undefined : identity}>
            {hasWatermark ? (
                <Box
                    aria-hidden
                    className="pointer-events-none absolute -bottom-6 -right-6 text-accent-soft-foreground opacity-40 [&_svg]:size-32"
                >
                    {Icon ? <Icon /> : null}
                </Box>
            ) : null}
            {hasWatermark ? <Box className="relative">{titleStack}</Box> : titleStack}
            {ctaNode ? (hasWatermark ? <Box className="relative">{ctaNode}</Box> : ctaNode) : null}
            {value === undefined ? null : <ProgressMeter value={value} max={max} />}
        </SectionCard>
    )

    // The clip/positioning context the watermark needs (see `hasWatermark` above) ΓÇö
    // scoped to just the card's own box so `HighlightCard`'s sweep (which
    // deliberately bleeds 2px past this same box) stays unclipped.
    const cardNode = hasWatermark
        ? <Box identity={identity} className="relative overflow-hidden rounded-3xl">{sectionCard}</Box>
        : sectionCard

    // `hero` = the ONE "resume the in-progress session" standout on its surface ΓÇö the
    // canonical `HighlightCard` case (`card.md` ┬º3j). `item` stays a static frame
    // (N of them together ΓÇö a highlighted card would just fight the others for
    // attention, same reasoning `withVerdict` never applied to `item` either).
    return isHero ? <HighlightCard>{cardNode}</HighlightCard> : cardNode
}

"use client"

import React from "react"
import {
    Card,
} from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/**
 * Loading placeholder mirroring the grid {@link import("../CourseCard").CourseCard}'s
 * layout (cover, title, 2 description lines, a 3-row value-prop list, price, and a
 * TWO-button action row) so the courses grid does not jump when data resolves.
 */
export const CourseCardSkeleton = () => {
    return (
        <Card className="flex flex-col overflow-hidden rounded-3xl">
            <Card.Content className="flex flex-col gap-3 p-0">
                {/* cover 16:9 */}
                <Skeleton className="aspect-video w-full rounded-2xl" />
                <div className="flex flex-col gap-2">
                    {/* title */}
                    <Skeleton.Typography type="h6" width="2/3" />
                    {/* description (line-clamp-2) */}
                    <Skeleton.Typography type="body-sm" width="full" />
                    <Skeleton.Typography type="body-sm" width="3/4" />
                    {/* value-props list (up to 3 check-icon rows) */}
                    <ul className="mt-1 flex flex-col gap-2">
                        {[0, 1, 2].map((index) => (
                            <li key={index} className="flex items-start gap-2">
                                <Skeleton className="size-4 shrink-0 rounded-full" />
                                <Skeleton.Typography type="body-xs" width="2/3" />
                            </li>
                        ))}
                    </ul>
                </div>
            </Card.Content>
            <Card.Footer className="mt-auto flex flex-col gap-2 pt-3">
                {/* price row */}
                <Skeleton.Typography type="body" width="1/3" />
                {/* action row ΓÇö primary + secondary button */}
                <div className="flex w-full items-center gap-2">
                    <Skeleton.Button width="flex-1" />
                    <Skeleton.Button width="flex-1" />
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, {
    useMemo,
    useState,
    type ComponentType,
} from "react"
import {
    ArrowRightIcon,
    BookOpenIcon,
    CheckCircleIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import {
    Button,
    Card,
    Chip,
    Typography,
    cn,
} from "@heroui/react"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { CourseEntity } from "@/modules/types/entities/course"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link _CourseCard} ΓÇö presentational; all data + labels already resolved. */
export interface CourseCardProps {
    /** The course summarised by this card (list-item data). */
    course: CourseEntity
    /**
     * Loyalty-discounted VND price (what THIS viewer is actually charged, from
     * `coursePricePreview`). When set it takes over the price block so the catalog
     * shows the same personalised price as the rest of the app; omit for the phase
     * price (guests / not-yet-loaded).
     */
    loyaltyPriceVnd?: number | null
    /** List/original VND price struck through under the loyalty price. */
    loyaltyOriginalVnd?: number | null
    /**
     * Whether the loyalty preview is still resolving (authenticated viewer only ΓÇö
     * guests never set this). Skeletons the price line instead of showing the
     * phase price and then swapping to the loyalty price a beat later.
     */
    loyaltyPending?: boolean
    /**
     * Layout: a roomy `"grid"` card (default ΓÇö cover + outcomes + price) or a
     * compact `"line"` row (thumbnail + title + price + CTA on one line). Lets the
     * catalog offer a grid Γçå list view toggle without a second card component.
     */
    layout?: "grid" | "line"
    /**
     * Optional trailing action node (e.g. an "Add to cart" button) rendered beside
     * the View CTA. The block only places it; the caller (a feature) owns its logic
     * so the card stays presentational.
     */
    action?: ComponentType
    /** Already-localized primary CTA label ("Continue learning" once enrolled, else "View course"). */
    viewLabel: string
    /** Already-localized secondary "View course" label, shown once enrolled (beside the primary CTA). */
    viewCourseLabel: string
    /** Already-localized "N learners" chip label; omitted when the course has no enrollments. */
    learnersLabel?: string
    /** Already-localized/formatted USD price hint line; omitted when there's no USD price. */
    priceUsdHintLabel?: string
    /** Fired by the primary CTA ΓÇö continue learning if enrolled, else go to the marketing page. */
    onView: () => void
    /** Fired by the secondary "View course" button shown once enrolled. */
    onViewDetail: () => void
}

/**
 * Featured course card (catalog block): cover (with branded fallback), title,
 * outcome, social proof + top value propositions, and a price block (active-phase
 * price, original strikethrough + % off when discounted, optional USD hint) with a
 * view CTA. Owns its whole look so features just feed the `course`.
 *
 * @param props - {@link CourseCardProps}
 */
export const _CourseCard = ({
    course,
    loyaltyPriceVnd,
    loyaltyOriginalVnd,
    loyaltyPending = false,
    layout = "grid",
    action: Action,
    viewLabel,
    viewCourseLabel,
    learnersLabel,
    priceUsdHintLabel,
    onView,
    onViewDetail,
}: CourseCardProps) => {
    const [coverFailed, setCoverFailed] = useState(false)

    // display transform for ENTITY-derived (fallback) VND prices so the catalog matches
    // the rest of the app: ├╖ testDivisor in non-prod. The loyalty price (from
    // `coursePricePreview`) is ALREADY transformed ΓåÆ not re-applied.
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))

    /** Active-phase price (falls back to the list/regular price when no phase row). */
    const currentPrice = useMemo(
        () => course.pricingPhases?.find(
            (pricingPhase) => pricingPhase.phase === course.currentPhase,
        )?.price ?? course.originalPrice ?? null,
        [course.pricingPhases, course.currentPhase, course.originalPrice],
    )

    /** Top three value propositions shown as a quick "what you'll learn" list. */
    const topValueProps = useMemo(
        () => (course.valuePropositions ?? []).slice(0, 3),
        [course.valuePropositions],
    )

    // enrolled ΓåÆ the marketing/detail page is the wrong destination for the PRIMARY
    // action (the viewer already owns this course); the connected half already routed
    // `onView` into the learning experience. The marketing page is still a legitimate
    // secondary destination once enrolled (re-check the syllabus, share the link).
    const isEnrolled = course.isEnrolled === true
    // not enrolled ΓåÆ the feature-owned `action` slot (cart-add, hides itself for
    // free/enrolled courses per its own logic). Enrolled ΓåÆ that slot would render
    // null anyway, so replace it with a secondary "View course" button (view the
    // marketing page) ΓÇö teacher: "a card for an already-purchased course should have
    // 2 parts: continue learning (primary) and view course (secondary)", don't just
    // drop the second button once enrolled.
    const secondaryAction = isEnrolled ? (
        // no trailing arrow ΓÇö arrow marks the ONE primary CTA per surface
        // (button.md ┬º2: "a button WITHOUT an icon = sub-CTA"); keeping it here as
        // well as on "Continue learning" made both buttons read as equally weighted.
        <Button
            variant="secondary"
            onPress={onViewDetail}
            className="flex-1"
        >
            {viewCourseLabel}
        </Button>
    ) : Action ? <Action /> : null

    const showCover = Boolean(course.coverImageUrl) && !coverFailed

    // price block: prefer the viewer's loyalty price (uniform with the rest of the app)
    // when supplied, else fall back to the active-phase price.
    const useLoyalty = loyaltyPriceVnd != null
    const displayPrice = useLoyalty
        ? loyaltyPriceVnd
        : (currentPrice != null ? toVnd(currentPrice) : null)
    const displayOriginal = useLoyalty
        ? loyaltyOriginalVnd ?? null
        : (course.originalPrice != null ? toVnd(course.originalPrice) : null)

    // compact LINE row (catalog list view): thumbnail + title/description, with the
    // price + view CTA on the right ΓÇö one course per row for fast scanning.
    if (layout === "line") {
        return (
            <Card className={cn("overflow-hidden rounded-3xl")}>
                {/* plain div, NOT Card.Content ΓÇö `.card__content` bakes flex-col
                    (unlayered), so `items-center` on it centers vertically instead of
                    laying the row out horizontally. The card root already insets its
                    children (baked `p-4`), so this row carries no padding of its own. */}
                <div className="flex items-center gap-3">
                    {/* thumbnail 16:9 (branded fallback); hidden on the narrowest screens.
                        rounded-2xl = the "inner" step under the card's rounded-3xl. */}
                    <div className="relative hidden aspect-video w-36 shrink-0 overflow-hidden rounded-2xl bg-surface @app-sm:block">
                        {showCover ? (
                            <img
                                src={course.coverImageUrl ?? undefined}
                                alt={course.title}
                                className="size-full object-cover"
                                onError={() => setCoverFailed(true)}
                            />
                        ) : (
                            <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5">
                                <BookOpenIcon aria-hidden className="size-8 text-accent-soft-foreground" />
                            </div>
                        )}
                    </div>
                    {/* title + one-line description */}
                    <div className="flex min-w-0 flex-1 flex-col gap-1">
                        <div className="flex items-center gap-2">
                            <Typography type="body" weight="bold" truncate>
                                {course.title}
                            </Typography>
                            {learnersLabel != null ? (
                                <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                    <UsersIcon aria-hidden className="size-4" />
                                    <Chip.Label>
                                        {learnersLabel}
                                    </Chip.Label>
                                </Chip>
                            ) : null}
                        </div>
                        <Typography type="body-sm" color="muted" className="line-clamp-1">
                            {course.description}
                        </Typography>
                    </div>
                    {/* price row, then a button row below ΓÇö view CTA is now a real primary
                        Button (not a subtle Link), per starci-fe-block-variants round-2
                        direction "C". `size="md"` per button.md ┬º3's compact-context
                        exception (a repeated grid card is a tight context ΓÇö `lg` would
                        blow up row height across many cards). */}
                    <div className="flex shrink-0 flex-col items-end gap-2">
                        {loyaltyPending ? (
                            <Skeleton.Typography type="body-sm" width="1/2" />
                        ) : displayPrice != null ? (
                            <PriceTagInline
                                discounted={displayPrice}
                                original={displayOriginal}
                               
                            />
                        ) : null}
                        <div className="flex w-full items-center gap-2">
                            <Button
                                variant="primary"
                                onPress={onView}
                                className="flex-1"
                            >
                                {viewLabel}
                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                            </Button>
                            {secondaryAction}
                        </div>
                    </div>
                </div>
            </Card>
        )
    }

    return (
        <Card className={cn("flex flex-col overflow-hidden rounded-3xl")}>
            <Card.Content className="flex flex-col gap-3">
                {/* cover 16:9 ΓÇö rounded-2xl = the "inner" step under the card's
                    rounded-3xl (was full-bleed/unrounded, mismatched the line thumb);
                    the card root already insets its children (baked `p-4`); branded
                    gradient fallback when missing/broken */}
                <div className="relative aspect-video w-full overflow-hidden rounded-2xl bg-surface">
                    {showCover ? (
                        <img
                            src={course.coverImageUrl ?? undefined}
                            alt={course.title}
                            className="size-full object-cover"
                            onError={() => setCoverFailed(true)}
                        />
                    ) : (
                        <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5 p-4">
                            <BookOpenIcon aria-hidden className="size-10 text-accent-soft-foreground" />
                            <Typography type="body-sm" weight="semibold" align="center" className="ml-2">
                                {course.title}
                            </Typography>
                        </div>
                    )}
                </div>

                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Typography type="h6" weight="bold" truncate>
                            {course.title}
                        </Typography>
                        {learnersLabel != null ? (
                            <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                <UsersIcon aria-hidden className="size-4" />
                                <Chip.Label>
                                    {learnersLabel}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                    </div>
                    <Typography type="body-sm" color="muted" className="line-clamp-2">
                        {course.description}
                    </Typography>
                    {topValueProps.length > 0 ? (
                        <ul className="mt-1 flex flex-col gap-2">
                            {topValueProps.map((valueProp, index) => (
                                <li key={index} className="flex items-start gap-2">
                                    <CheckCircleIcon aria-hidden className="size-4 shrink-0 text-success-soft-foreground" />
                                    <Typography type="body-xs" color="muted">
                                        {valueProp.text}
                                    </Typography>
                                </li>
                            ))}
                        </ul>
                    ) : null}
                </div>
            </Card.Content>
            <Card.Footer className="mt-auto flex flex-col gap-2">
                {/* price row (informational) */}
                <div className="flex items-center gap-2">
                    {loyaltyPending ? (
                        <Skeleton.Typography type="body-sm" width="1/2" />
                    ) : displayPrice != null ? (
                        <PriceTagInline
                            discounted={displayPrice}
                            original={displayOriginal}
                           
                        />
                    ) : (
                        <span />
                    )}
                </div>
                {priceUsdHintLabel != null ? (
                    <Typography type="body-xs" color="muted">
                        {priceUsdHintLabel}
                    </Typography>
                ) : null}
                {/* action row ΓÇö view CTA is a real primary Button (not a subtle Link), per
                    starci-fe-block-variants round-2 direction "C": the previous accent Link
                    read as a secondary "see more" action rather than the card's actual primary
                    action. `size="md"` per button.md ┬º3's compact-context exception (a
                    repeated grid card is tight ΓÇö `lg` would blow up card height across many
                    cards). Cart-add stays `action` (secondary, pairs with this primary). */}
                <div className="flex w-full items-center gap-2">
                    <Button
                        variant="primary"
                        onPress={onView}
                        className="flex-1"
                    >
                        {viewLabel}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                    </Button>
                    {secondaryAction}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, { useState, type ComponentType } from "react"
import { ScrollShadow, cn } from "@heroui/react"
import { AnimatePresence, motion } from "framer-motion"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"

/** Props for the {@link FlipCard} block. */
export interface FlipCardProps {
    /** Whether the answer card is currently revealed below the question. */
    revealed: boolean
    /** Label shown OUTSIDE (above) the question card ΓÇö e.g. "Question". */
    questionLabel: string
    /** Label shown OUTSIDE (above) the answer card ΓÇö e.g. "Answer". */
    answerLabel: string
    /** Front (prompt) content ΓÇö a buildable slot that sits in the question card. */
    front: ComponentType
    /**
     * Optional slot rendered DIRECTLY under the question card (grouped with it,
     * `gap-3`) ΓÇö ABOVE the answer, so it stays anchored to the question when the
     * answer reveals below (teacher 2026-07-13: "chips gap-3 under the question"). Used for
     * the card's level/tag chips.
     */
    belowFront?: ComponentType
    /** Back (answer) content ΓÇö a buildable slot shown once {@link revealed}. */
    back: ComponentType
}

/**
 * Anki-style "no-flip" prompt/answer pair: the question and the answer are TWO
 * SEPARATE {@link LabeledCard}s ΓÇö each label ("Question" / "Answer") sits OUTSIDE,
 * above its card (teacher 2026-07-12: "question, answer outside as a labeled card"),
 * not an eyebrow inside the card. The answer card reveals below the question one
 * (height-animate) once {@link revealed}. Retrieval-practice research (teacher
 * 2026-07-11) says what matters for recall is committing to an answer BEFORE
 * seeing it ΓÇö the caller owns the "Show answer" reveal control and renders it
 * BETWEEN this block and the rating; this block is purely presentational.
 * @param props - {@link FlipCardProps}
 */
export const FlipCard = ({ revealed, questionLabel, answerLabel, front: Front, belowFront: BelowFront, back: Back}: FlipCardProps) => {
    // `overflow-hidden` is only needed WHILE the height animates ΓÇö left on at
    // rest, it permanently clips the answer `Card`'s own box-shadow along every
    // edge, so it read flatter than the question card right above it (teacher:
    // "can the yellow one render as a card like the red one, with a
    // shadow..."). Drop it once the reveal animation settles so the shadow
    // shows in full, same as the un-clipped question card.
    const [animating, setAnimating] = useState(false)
    return (
        <div className={"flex flex-col gap-6"}>
            {/* question card + its `belowFront` chips grouped `gap-3` ΓÇö the chips
                stay under the QUESTION when the answer reveals below (not pushed
                to the bottom of the answer). */}
            <div className="flex flex-col gap-3">
                <LabeledCard label={questionLabel} bordered>
                    <Front />
                </LabeledCard>
                {BelowFront ? <BelowFront /> : null}
            </div>
            {/* answer = its OWN labeled card, revealed below (height-animate so the
                reveal still feels connected) */}
            <AnimatePresence initial={false}>
                {revealed ? (
                    <motion.div
                        key="answer"
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.25, ease: "easeInOut" }}
                        onAnimationStart={() => setAnimating(true)}
                        onAnimationComplete={() => setAnimating(false)}
                        className={cn(animating && "overflow-hidden")}
                    >
                        <LabeledCard label={answerLabel} bordered>
                            <ScrollShadow hideScrollBar className="flex max-h-[28rem] flex-col gap-3 overflow-y-auto text-left">
                                <Back />
                            </ScrollShadow>
                        </LabeledCard>
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

"use client"

import React, { useEffect, type ComponentType } from "react"
import { cn } from "@heroui/react"
import { PressableCard } from "@/components/blocks/cards/PressableCard"
import { type VerdictBand, verdictBandClassName } from "@/components/blocks/cards/verdict-band"

/**
 * Column count per CONTAINER width ΓÇö these are container queries, not viewport
 * breakpoints. A block cannot know where it is placed: the same grid may sit in a
 * full page column or in a 256px rail, and a viewport breakpoint gets the rail
 * case wrong every time (wide window + narrow slot = cards crushed to a sliver).
 * Steps mirror Tailwind v4's container sizes, so the key IS the class suffix.
 */
export interface GroupPressableCardColumns {
    /** Columns at the narrowest. Defaults to `1`. */
    base?: 1 | 2
    /** From a 24rem / 384px container. */
    sm?: 2 | 3 | 4
    /** From a 28rem / 448px container. */
    md?: 2 | 3 | 4
    /** From a 32rem / 512px container. */
    lg?: 2 | 3 | 4
    /** From a 36rem / 576px container. */
    xl?: 2 | 3 | 4
    /** From a 48rem / 768px container. */
    xl3?: 2 | 3 | 4
    /** From a 56rem / 896px container. */
    xl4?: 2 | 3 | 4
}

/** One pressable card inside a {@link GroupPressableCard}. */
export interface GroupPressableCardItem {
    /** Stable React key. Also fixes the item's position for the 1ΓÇôN shortcut. */
    key: string
    /** Card body ΓÇö a buildable slot composed freely by the caller (icon tiles, text, chipsΓÇª). */
    content: ComponentType
    /** Press handler. Ignored when {@link GroupPressableCardItem.href} is set. */
    onPress?: () => void
    /** Navigation target ΓÇö renders this card as an anchor. */
    href?: string
    /** Dims the card and blocks both pressing and the keyboard shortcut. */
    isDisabled?: boolean
    /** Accessible name ΓÇö needed only when {@link GroupPressableCardItem.content} carries no readable text. */
    label?: string
    /**
     * Forwarded to this card's own `className` ΓÇö for grid placement (`@lg:col-start-2`
     * to pin a lone card to the right column) and for tile-level tweaks on top of
     * the `PressableCard` surface (a tighter `rounded-xl px-3 py-2` rating tile).
     *
     * Placement classes must use the **container** variant (`@lg:`), NOT the viewport
     * one (`lg:`), and must name the SAME step at which
     * {@link GroupPressableCardProps.columns} actually reaches that column ΓÇö a
     * `col-start-2` that outruns the column count lands in an implicit,
     * content-sized track and squeezes the card to a sliver.
     */
    className?: string
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this tile with a signal that
     * comes from DATA (`card.md` ┬º3i) ΓÇö e.g. the SM-2 recall grade's tier. The canonical
     * {@link VerdictBand} (`variant` semantic, or `color` raw-palette escape hatch), the
     * SAME shape as `SectionCard`/`SurfaceListCardItem`.
     */
    withVerdict?: VerdictBand
}

/** Props for the {@link GroupPressableCard} block. */
export interface GroupPressableCardProps {
    /** The cards, in reading order (also the 1ΓÇôN shortcut order). */
    items: Array<GroupPressableCardItem>
    /**
     * Accessible name for the whole group ΓÇö REQUIRED. Without it a screen reader
     * hears N loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** Responsive column count. Defaults to a single column. */
    columns?: GroupPressableCardColumns
    /** Gap between cards on the spacing scale. Defaults to `3`. */
    gap?: 2 | 3
    /**
     * Binds number keys `1`ΓÇô`N` to the items in order, so the group can be driven
     * without the mouse. Off by default ΓÇö only opt in where the group IS the
     * screen's primary action (e.g. a flashcard rating bar), never for an
     * incidental grid of navigation tiles that would hijack digits globally.
     */
    keyboardShortcut?: boolean
}

// Compact grid cell, not a standalone top-level card: one step down from
// `PressableCard`'s own `rounded-3xl`/`shadow-surface` default (concentric
// radius: card 24px ΓêÆ 1 step ΓåÆ 16px) and one step UP from the flat button /
// `shadow-field` input ΓÇö `GroupPressableCard` is the ONLY place this chrome
// lives; `PressableCard` used standalone (a real full-size card, e.g.
// `ConsultantCard`) keeps its own bigger default untouched.
const TILE_CHROME = "rounded-2xl shadow-field"

// Tailwind needs LITERAL class strings ΓÇö `@sm:grid-cols-${n}` interpolation is
// never emitted by the compiler, so each supported count maps to a written-out
// class. The `@` prefix = container query (Tailwind v4 core, no plugin).
/** Grid template per base column count. */
const BASE_COLUMNS_CLASS: Record<1 | 2, string> = {
    1: "grid-cols-1",
    2: "grid-cols-2",
}
/** Container-step key ΓåÆ its literal class map, applied in ascending width order. */
const STEP_COLUMNS_CLASS: Record<
    Exclude<keyof GroupPressableCardColumns, "base">,
    Record<2 | 3 | 4, string>
> = {
    sm: { 2: "@sm:grid-cols-2", 3: "@sm:grid-cols-3", 4: "@sm:grid-cols-4" },
    md: { 2: "@md:grid-cols-2", 3: "@md:grid-cols-3", 4: "@md:grid-cols-4" },
    lg: { 2: "@lg:grid-cols-2", 3: "@lg:grid-cols-3", 4: "@lg:grid-cols-4" },
    xl: { 2: "@xl:grid-cols-2", 3: "@xl:grid-cols-3", 4: "@xl:grid-cols-4" },
    xl3: { 2: "@3xl:grid-cols-2", 3: "@3xl:grid-cols-3", 4: "@3xl:grid-cols-4" },
    xl4: { 2: "@4xl:grid-cols-2", 3: "@4xl:grid-cols-3", 4: "@4xl:grid-cols-4" },
}
/** Ascending container-step order ΓÇö later steps must win, so emit them in width order. */
const STEP_ORDER = ["sm", "md", "lg", "xl", "xl3", "xl4"] as const
/** Gap class per supported spacing step. */
const GAP_CLASS: Record<2 | 3, string> = {
    2: "gap-2",
    3: "gap-3",
}

/**
 * A grid of `PressableCard`s that act and then get out of the way ΓÇö the whole
 * group is ONE labelled unit (`role="group"` + `aria-label`), each cell is a
 * canonical `PressableCard`, and the cards' bodies stay the caller's to compose.
 *
 * Exists because a bare `<div className="grid">` of cards leaves a screen reader
 * hearing N loose buttons with nothing tying them together, and because the same
 * responsive-grid + keyboard plumbing was being hand-rolled at every call site.
 *
 * Reflows on the CONTAINER's width, not the viewport's ({@link GroupPressableCardColumns}) ΓÇö
 * a reusable block does not know whether it was dropped into a full page column or
 * a 256px rail, and a viewport breakpoint reads a wide window as "I have room" even
 * when the actual slot is a sliver.
 *
 * **Not a selection control.** Nothing here stays "chosen": press a card and the
 * surface acts (grade the card, open the page) ΓÇö so these are ACTIONS, not radios.
 * When the pick must PERSIST and read back as "this is my choice", use
 * `SelectableCardGroup` instead (a real HeroUI `RadioGroup`: `value`/`onChange`,
 * accent outline on the selected card, arrow-key roving). Deliberately no
 * `selected` prop here ΓÇö that boundary is the whole point of two blocks.
 *
 * @param props - {@link GroupPressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/GroupPressableCard/GroupPressableCard.stories
 */
export const GroupPressableCard = ({
    items,
    ariaLabel,
    columns = {},
    gap = 3,
    keyboardShortcut = false,
}: GroupPressableCardProps) => {
    // `items` is typically rebuilt inline by the caller (`options.map(...)`), so a
    // fresh array arrives every render. Reading it through a ref keeps the window
    // listener subscribed ONCE instead of tearing down and re-adding on each pass,
    // while the handler still sees the current items.
    const itemsRef = React.useRef(items)
    useEffect(() => {
        itemsRef.current = items
    }, [items])

    // Press 1ΓÇôN to act without reaching for the mouse. Opt-in: the listener is
    // on `window`, so a group that isn't the screen's main action would steal
    // every digit the page sees.
    useEffect(() => {
        if (!keyboardShortcut) {
            return
        }
        const onKeyDown = (event: KeyboardEvent) => {
            // never hijack a digit the user is typing into a field
            const target = event.target as HTMLElement | null
            if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) {
                return
            }
            const position = Number(event.key) - 1
            const current = itemsRef.current
            if (!Number.isInteger(position) || position < 0 || position >= current.length) {
                return
            }
            const item = current[position]
            if (item.isDisabled || !item.onPress) {
                return
            }
            event.preventDefault()
            item.onPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [keyboardShortcut])

    // an empty group would announce a label with nothing under it
    if (items.length === 0) {
        return null
    }

    return (
        // The `@container` wrapper is NOT decorative: an element cannot query its
        // own size, so the queried grid must live inside the container it reacts to.
        <div className="@container">
            <div
                role="group"
                aria-label={ariaLabel}
                className={cn(
                    "grid",
                    GAP_CLASS[gap],
                    BASE_COLUMNS_CLASS[columns.base ?? 1],
                    STEP_ORDER.map((step) => {
                        const count = columns[step]
                        return count === undefined ? undefined : STEP_COLUMNS_CLASS[step][count]
                    }),
                )}
            >
                {items.map((item) => {
                    const Content = item.content
                    return (
                        <PressableCard
                            key={item.key}
                            onPress={item.onPress}
                            href={item.href}
                            isDisabled={item.isDisabled}
                            label={item.label}
                            className={cn(
                                TILE_CHROME,
                                // canonical verdict left-band (shape + colour + !important fix)
                                verdictBandClassName(item.withVerdict),
                                item.className,
                            )}
                        >
                            <Content />
                        </PressableCard>
                    )
                })}
            </div>
        </div>
    )
}

