import React from "react"
/** Props for {@link HighlightCard}. */
export interface HighlightCardProps {
    /** The wrapped card (e.g. a `SectionCard`/`Card`) ΓÇö `HighlightCard` only adds the sweeping-light layer, it renders no card chrome of its own. */
    children: React.ReactNode
}

/**
 * Wraps a card with a single accent-colored arc SWEEPING around it, sitting as its own
 * layer BEHIND it (peeking out past the edges by 2px) ΓÇö a pure "stand-out"
 * decoration, NOT a data signal (contrast with `SectionCard`'s `withVerdict`, a static
 * left band that DOES encode band/tier/zone data ΓÇö `card.md` ┬º3i vs ┬º3j). Renders as 2
 * stacked cards: the INNER layer (bigger, behind, carries the sweeping-light effect) and
 * the wrapped card itself (OUTER, in front, 2px smaller in radius) ΓÇö see `card.md` ┬º3j
 * for why this is 2 layers and not a `SectionCard` prop. Use for the ONE card that
