        {children}
    </div>
)

"use client"

import React, { type ComponentType } from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Image } from "@/components/atoms/media/Image"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"

/** Placeholder cover when {@link MediaCardProps.cover} is omitted ΓÇö 16:9. */
const FALLBACK_COVER_SRC = "https://placehold.co/640x360"

/** Props for {@link MediaCard}. */
export interface MediaCardProps {
    /**
     * Optional media node rendered flush at the very top of the card, edge-to-
     * edge under the card radius (e.g. an `<img>`). When omitted, a 16:9
     * placeholder image fills the same full-bleed slot.
     */
    cover?: ComponentType
    /**
     * Primary heading of the card (course / lesson / challenge / blog title).
     * Rendered via {@link Typography} weight="medium" (body size).
     */
    title: string
    /**
     * Optional metadata row shown directly under the title ΓÇö typically a row of
     * chips or muted text (category, difficulty, duration, author).
     */
    meta?: ComponentType
    /**
     * Optional short description / excerpt. Rendered muted, clamped to two
     * lines so grid rows stay uniform.
     */
    description?: string
    /**
     * Optional footer pinned at the bottom of the body ΓÇö typically a CTA button,
     * price, or progress indicator.
     */
    footer?: ComponentType
    /**
     * Optional press handler. When provided the whole card becomes pressable and
     * keyboard-accessible. Prefer {@link href} for pure navigation.
     */
    onPress?: () => void
    /**
     * Optional destination URL. When provided the card renders as an anchor so
     * the whole card is a single accessible link.
     */
    href?: string
    /**
     * Where this card sits inside its parent. Appearance is not passable ΓÇö it is
     * already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Consolidated, presentational content card ΓÇö one shape for course / lesson /
 * challenge / blog grids. Composes {@link SurfaceCard} for the card face itself
 * (the `nested` variant gives the flat, border-not-shadow look this card has
 * always had ΓÇö globals still supply the 3xl radius) so this file owns no card
 * chrome of its own: a flush 16:9 cover slot on top, and a padded stack of
 * title / meta / description / footer underneath. When {@link cover} is
 * omitted a 16:9 placeholder image fills that slot.
 *
 * Pass `href` for navigation or `onPress` for a custom handler ΓÇö either makes
 * the whole card pressable and keyboard-accessible via `SurfaceCard`'s own
 * press handling (ripple + press-scale for `onPress`, a real anchor for
 * `href`).
 *
 * @param props - {@link MediaCardProps}
 * @see Story: .storybook/stories/blocks/cards/MediaCard/MediaCard.stories
 */
export const MediaCard = ({
    cover: Cover,
    title,
    meta: Meta,
    description,
    footer: Footer,
    onPress,
    href,
    classNames,
}: MediaCardProps) => {
    const coverNode = Cover
        ? <Cover />
        : <Image src={FALLBACK_COVER_SRC} alt="" ratio="video" radius="none" />

    const body = () => (
        <StackV
            gap={1}
            items={[
                () => (
                    <Box className="aspect-video w-full shrink-0 overflow-hidden [&_img]:block [&_img]:size-full [&_img]:object-cover">
                        {coverNode}
                    </Box>
                ),
                () => (
                    <StackV
                        gap={1}
                        padding={5}
                        principle="card-padding"
                        explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome."
                        body={() => (
                            <StackV
                                gap={4}
                                principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                items={[
                                    () => <Typography size="base" weight="medium" text={title} />,
                                    ...(Meta ? [() => <Cluster gap={3} principle="chip-row"
                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                        items={[() => <Meta />]} />] : []),
                                    ...(description ? [() => <Typography size="sm" color="muted" lineClamp={2} text={description} />] : []),
                                    ...(Footer ? [() => <Footer />] : []),
                                ]}
                            />
                        )}
                    />
                ),
            ]}
        />
    )

    return (
        <SurfaceCard identity={{ tier: "block", component: "MediaCard" }}
            variant="nested"
            padding={1}
            onPress={onPress}
            href={href}
            body={body}
            classNames={classNames}
        />
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * Props for the {@link PressableCard} block.
 *
 * TIER NOTE: this folder sits under `blocks/cards`, but the component itself
 * owns no domain entity ΓÇö every prop here is a shape (`children`, `onPress`,
 * `href`, `actions`) never a field of something fetched. That is BLOCK-7's
 * detection signal: it is really a **composite** mis-filed in a block folder.
 * Left in place (moving the folder breaks every importer below), but treated
 * as a composite for this pass ΓÇö one file, `cn()` allowed (COMPOSITE-5), and
 * `className` kept as a raw string rather than `classNames: Array<AllowedClassName>`
 * because three real callers outside this folder (`GroupPressableCard`,
 * `SummaryCard`, `ConsultantCard`) already forward arbitrary skin classes
 * (radius/border/hover overrides) through it ΓÇö narrowing the type here would
 * break them without touching a single one of their files.
 *
 * `composites/cards/SurfaceCard` (`SurfaceCard`, exported off `Base`) is the
 * emerging canonical member for this exact job ΓÇö same whole-card press target,
 * same stretched-link `actions` pattern, plus ripple/selection/verdict-band ΓÇö
 * and its own header explicitly notes it folds in "was `PressableCard`". It is
 * NOT swapped in here: its hover/ripple treatment differs from this file's
 * (tint-on-hover, no ripple), so delegating to it would change the rendered
 * look for the three live callers above, not just the code shape. Consolidating
 * onto `SurfaceCard` is a separate migration (each caller needs the `children`
 * ΓåÆ `body` slot conversion too), left as debt rather than folded in silently.
 */
export interface PressableCardProps extends WithClassNames<undefined> {
    /** Card body ΓÇö composed freely by the caller (icon tiles, text, chipsΓÇª). */
    children: React.ReactNode
    /**
     * Press handler for an action card (select / toggle). Ignored when
     * {@link PressableCardProps.href} is set. One of `onPress` / `href` should
     * be provided for the card to be interactive.
     */
    onPress?: () => void
    /** Navigation target ΓÇö renders the card as an anchor when provided. */
    href?: string
    /** Disables interaction and dims the card (action cards only). */
    isDisabled?: boolean
    /**
     * Secondary interactive controls (buttons / menus) that live INSIDE the card
     * but act INDEPENDENTLY of the whole-card press ΓÇö e.g. a "Continue" button +
     * an overflow menu on a course-progress card.
     *
     * Providing this switches the card to the accessible **stretched-link**
     * pattern (Inclusive Components / Adrian Roselli): the whole-card target
     * becomes a TRANSPARENT overlay that covers the card, and these actions sit
     * ABOVE it (later in source order + `z-10`) so each stays separately
     * clickable. This is the correct alternative to illegally nesting a
     * `<button>` inside the card's own `<button>`/`<a>` ΓÇö which is invalid HTML,
     * breaks the keyboard/AT focus order, AND is what made the card grow tall
     * (a block button laying its interactive children out on their own lines).
     *
     * REQUIRES {@link PressableCardProps.label} ΓÇö the overlay target no longer
     * wraps the children text, so it needs its own accessible name.
     */
    actions?: ComponentType
    /**
     * Accessible name for the whole-card press target. REQUIRED when
     * {@link PressableCardProps.actions} is set (the stretched overlay covers the
     * card but has no visible text of its own, so it must carry an `aria-label`).
     * Optional otherwise ΓÇö without `actions` the children ARE the card's
     * accessible name, so pass this only when they carry no readable text (an
     * icon-only tile). Keep it descriptive of the destination/action ("Open the
     * Fullstack Mastery track"), never generic ("click here").
     */
    label?: string
    /**
     * Caller identity to wear on this card's root instead of its own ΓÇö pass this
     * when a sentence-tier component roots on this card (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * A whole-card press target with the default surface card look (surface fill,
 * concentric `rounded-3xl`, fixed `px-4 py-3` padding, `shadow-surface`
 * elevation AT REST ΓÇö per `card.md` ┬º0, a top-level bounded card, so it must
 * read as a card even before hover) plus a hover affordance and keyboard
 * focus ring. Exists because HeroUI v3 `Card` is a
 * non-interactive `<div>` ΓÇö this component owns the card styling on a real
 * `<button>` / `<a>` so features can compose a clickable card without
 * hand-rolling styles (per the no-style-in-features rule). Use for navigation
 * tiles, selectable option cards, and bookmark rows.
 *
 * When the card also needs its OWN buttons (a "Continue" CTA, an overflow menu),
 * pass them via {@link PressableCardProps.actions} + {@link PressableCardProps.label}:
 * the card renders as the accessible stretched-link pattern (a transparent
 * whole-card overlay UNDER the actions) instead of nesting interactive elements
 * ΓÇö see the `actions` prop docs.
 *
 * @param props - {@link PressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/PressableCard/PressableCard.stories
 */
export const PressableCard = ({
    children,
    onPress,
    href,
    isDisabled = false,
    actions: Actions,
    label,
    className,
    identity,
}: PressableCardProps) => {
    // Shared card surface + disabled dim, identical across both render paths so
    // a card reads the same with or without actions. `shadow-surface` is a
    // top-level bounded card (card.md ┬º0 elevation convention) ΓÇö it must read as
    // one at rest, not only once the pointer arrives (teacher: "render it as a card").
    // One hover treatment only (tint) ΓÇö no lift variant, no press-scale.
    const surface = cn(
        "rounded-3xl bg-surface px-4 py-3 text-left shadow-surface transition-colors hover:bg-surface-secondary",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "PressableCard" })

    // ΓöÇΓöÇ Simple whole-card target (no secondary actions) ΓÇö the common case;
    // the whole card is ONE <button>/<a> and its children are its label. ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (!Actions) {
        const base = cn(
            "block w-full outline-none focus-visible:ring-2 focus-visible:ring-accent",
            surface,
        )
        if (href && !isDisabled) {
            return (
                <a href={href} aria-label={label} className={base} {...identityAttrs}>
                    {children}
                </a>
            )
        }
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                aria-label={label}
                className={cn(base, !isDisabled && "cursor-pointer")}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }

    // ΓöÇΓöÇ Card WITH its own buttons ΓÇö stretched-link pattern. The card is a plain
    // relative <div>; a transparent overlay <a>/<button> covers it (whole-card
    // press), and the actions sit ABOVE the overlay so they stay clickable. No
    // interactive element is ever nested inside another. Row built with `StackH`
    // (frame tier) instead of a hand-rolled `flex items-center gap-3` wrapper ΓÇö
    // same shape as `composites/cards/SurfaceCard`'s own actions branch. ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const overlay = cn(
        // covers the whole card; the focus ring reads as a card-level ring since
        // the overlay's border-box IS the card's bounds
        "absolute inset-0 rounded-3xl outline-none focus-visible:ring-2 focus-visible:ring-accent",
        isDisabled ? "cursor-not-allowed" : "cursor-pointer",
    )
    return (
        <div className={cn("relative w-full", surface)} {...identityAttrs}>
            <StackH
                principle="content-row"
                explain="Card body and trailing actions share one content row ΓÇö not flex-action, because the body is content rather than a control peer."
                items={[
                    () => (
                        <FillAvailable
                            at="base"
                            explain="Card body takes remaining row width beside the actions cluster so long titles truncate instead of shoving the actions."
                            body={() => <>{children}</>}
                        />
                    ),
                    () => (
                        <div className="relative z-10">
                            <StackH
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={[() => <Actions />]}
                            />
                        </div>
                    ),
                ]}
            />
            {href && !isDisabled ? (
                <a href={href} aria-label={label} className={overlay} />
            ) : (
                <button
                    type="button"
                    onClick={onPress}
                    disabled={isDisabled}
                    aria-label={label}
                    className={overlay}
                />
            )}
        </div>
    )
}

"use client"

import React, { type ComponentType } from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { type AllowedGap, type LayoutAlign } from "@/components/frames/_spacing"
import { type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/** Props for {@link SectionCard}. */
export interface SectionCardProps {
    /** Card body. */
    children: React.ReactNode
    /** Optional section title rendered in the header row. The atom wraps it in `Typography` itself. */
    title?: string
    /** Optional leading icon shown before the title ΓÇö a buildable slot, not a built element. */
    icon?: ComponentType
    /** Optional action slot pinned to the right of the header (button/link) ΓÇö a buildable slot. */
    action?: ComponentType
    /** Accent variant: tinted border + background (highlight / "yours"). */
    accent?: boolean
    /**
     * Verdict variant: a thick LEFT band (`border-l-4`) on top of the card's own
     * border ΓÇö the asymmetric-border shape for "a card carrying a signal FROM DATA"
     * (`card.md` ┬º3i). See {@link VerdictBand}. Left band ONLY reads as a DATA
     * signal ΓÇö never ad-hoc "active region" decoration (`card.md` ┬º3g).
     */
    withVerdict?: VerdictBand
    /**
     * Where the card sits inside its parent. Appearance is not passable ΓÇö it is
     * already a prop.
     *
     * missingVocabulary (no-classname-at-sentence-tier, BLOCK-4): `QuizCard`, `MetricCard`, and
     * `PitchCard` all genuinely forward a value through here today. Dropping this prop would
     * require editing those call sites too, and they sit outside this folder ΓÇö left in place and
     * flagged as known debt rather than silently removed.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Seam between the header row (when present) and `children`, and between items inside
     * `children` that opt into the same track ΓÇö the content wrapper's own gap step on the
     * house scale (`AllowedGap`, `_spacing.ts`). Defaults to `4` (`gap-3`), the shape every
     * caller got before this prop existed. `PricingCard` needs a roomier `6` (`gap-6`) between
     * its name/price/features/cta rows.
     */
    contentGap?: AllowedGap
    /**
     * `true` ΓåÆ the content wrapper stretches to fill the card's height (`h-full`) instead of
     * hugging its own content. For cards placed side-by-side in a grid (`PricingCard`,
     * `PitchCard`, the `ContinueLearning` skeleton shell) so the CTA/footer row still pins to
     * the bottom even when a sibling card's copy runs longer. Defaults to `false`.
     */
    fillHeight?: boolean
    /**
     * Cross-axis alignment of the content wrapper's track. Defaults to `"stretch"` (every child
     * takes the full width), matching the shape every caller got before this prop existed. The
     * `ContinueLearning` empty state needs `"start"` so its CTA button hugs its own width
     * instead of stretching full-bleed.
     */
    contentAlign?: LayoutAlign
    /**
     * Caller identity to wear on this card's root element instead of its own ΓÇö pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this card AS its root element, instead of wrapping it in a raw `<div data-tier=ΓÇª
     * data-component=ΓÇª>`. See `_identity.ts`. Omitted ΓåÆ this card keeps emitting its own
     * `data-tier="block" data-component="SectionCard"`, unchanged.
     */
    identity?: CallerIdentity
}

/**
 * The canonical bordered "framed" card used across profile + dashboard. A thin
 * skin (`rounded-3xl bg-surface shadow-surface`, the same face `.card` in
 * `globals.css` gives HeroUI's own `Card`) that adds an optional header row
 * (icon + title on the left, action on the right) so every titled section looks
 * identical. Use `accent` for the viewer's own / highlighted cards. The header
 * row and content wrapper compose the frame tier's `StackH`/`StackV`/`Box`.
 *
 * @param props - {@link SectionCardProps}
 * @see Story: .storybook/stories/blocks/cards/SectionCard/SectionCard.stories
 */
export const SectionCard = ({
    children,
    title,
    icon: Icon,
    action: Action,
    accent = false,
    withVerdict,
    classNames,
    contentGap = 4,
    fillHeight = false,
    contentAlign = "stretch",
    identity,
}: SectionCardProps) => {
    const hasHeader = Boolean(title || Action || Icon)
    // BLOCK-5 DEBT, left VISIBLE on purpose: this block decides its own card face ΓÇö
    // radius ┬╖ surface ┬╖ shadow ┬╖ padding ┬╖ accent border ┬╖ verdict band ΓÇö which is a
    // lower tier's job; read it as "a composite is missing". An earlier pass hid this by
    // hand-joining the array so the `cn` rule would not fire, which changed nothing about
    // the design. The real fix is to compose `composites/cards/SurfaceCard`'s face, a
    // migration of its own.
    const rootClassName = cn(
        "rounded-3xl bg-surface shadow-surface p-4",
        accent ? "border-accent" : null,
        verdictBandClassName(withVerdict),
        ...(classNames ?? []),
    )
    return (
        <Box
            identity={identity ?? { tier: "block", component: "SectionCard" }}
            className={rootClassName}
        >
            <StackV
                gap={contentGap}
                principle={contentGap === 6 ? "block-boundary" : contentGap === 5 ? "group-boundary" : "card-caption"}
                explain={
                    contentGap === 6
                        ? "Separates the section header from the card body as major regions so a roomier PricingCard rhythm does not collapse into one band."
                        : contentGap === 5
                            ? "Spaces the header band and body as distinct section groups so they stay as separate bands rather than a flat peer list."
                            : "Stacks the optional header above the body so the title row stays on its own track above the card content."
                }
                align={contentAlign}
                classNames={fillHeight ? ["h-full"] : undefined}
                body={() => (
                    <>
                        {hasHeader ? (
                            <Box className="border-b border-separator pb-3">
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    justify="between"
                                    items={[
                                        () => (
                                            <StackH
                                                gap={2}
                                                principle="icon-text"
                                                explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                classNames={["min-w-0"]}
                                                items={[
                                                    ...(Icon ? [() => <Icon />] : []),
                                                    ...(title ? [() => (
                                                        <Typography size="base" weight="semibold" truncate text={title} />
                                                    )] : []),
                                                ]}
                                            />
                                        ),
                                        ...(Action ? [() => <span className="shrink-0"><Action /></span>] : []),
                                    ]}
                                />
                            </Box>
                        ) : null}
                        {children}
                    </>
                )}
            />
        </Box>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import {
    CaretRightIcon as ChevronRightIcon,
} from "@phosphor-icons/react"
import {
    PressableCard,
} from "../PressableCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Props for {@link SummaryCard}. Every field is an already-resolved shape
 * (icon, value, label, hint) ΓÇö this card takes no domain entity, which is
 * why it lives at the composite tier despite sitting in `blocks/cards`
 * (BLOCK-7): the folder names a tier the component never earned.
 */
export interface SummaryCardProps {
    /** Leading icon for the metric ΓÇö a buildable slot, not a built element. */
    icon: ComponentType
    /** Headline value (e.g. a count). */
    value: string
    /** Short label under the value. */
    label: string
    /** Optional one-line hint under the label. */
    hint?: string
    /** Called when the card is activated (e.g. jump to a tab). */
    onPress?: () => void
}

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "SummaryCard" } as const

/**
 * A compact pressable metric card (icon + big value + label, with a trailing
 * chevron) used in the profile overview to surface a deeper tab. Built on
 * {@link PressableCard} for the spring/hover feel; layers its own outlined
 * "default" card look on top of that surface. Presentational ΓÇö the caller
 * wires `onPress`.
 *
 * `PressableCard` has not itself been ported to the closed `classNames`
 * vocabulary, so its `className` string prop is composed here with `cn`
 * (COMPOSITE-5 ΓÇö appearance is this tier's job); `SummaryCard` renders no
 * `<div>` of its own beyond what `PressableCard`'s button/anchor already
 * emits, so it carries no separate `data-tier`/`data-component` badge ΓÇö
 * `PressableCard` offers no slot for one, and wrapping it in an extra `<div>`
 * just to hang the badge on would be the identity wrapper the composite tier
 * says not to add.
 *
 * @param props - {@link SummaryCardProps}
 */
export const SummaryCard = ({
    icon: Icon,
    value,
    label,
    hint,
    onPress,
}: SummaryCardProps) => {
    const rows = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between"
                items={[
                    () => <span className="text-accent-soft-foreground"><Icon /></span>,
                    () => <ChevronRightIcon className="size-5 text-muted" />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={1}
                items={[
                    () => <Typography size="h4" weight="bold" text={value} />,
                    () => <Typography size="sm" weight="medium" text={label} />,
                    ...(hint ? [() => <Typography size="xs" color="muted" text={hint} />] : []),
                ]}
            />
        ),
    ]

    return (
        <PressableCard
            identity={{ tier: "block", component: "SummaryCard" }}
            onPress={onPress}
            className={cn(
                "card card--default h-full rounded-xl border border-divider/60 p-4 transition-colors",
                "hover:border-accent/40 hover:bg-accent/5",
            )}
        >
            <StackV gap={4} items={rows} />
        </PressableCard>
    )
}

"use client"

import React, { type ComponentType } from "react"
import Link from "next/link"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/**
 * The interactive anchor for a clickable surface-list row. An INTERNAL app route
 * (href starting with `/`) renders a Next `<Link>` ΓåÆ client-side `router.push`:
 * SPA navigation that keeps history (Back works) with NO full-page reload ΓÇö and
 * NEVER `router.replace` (a link click must not erase the entry it came from).
 * Protocol / external hrefs (`mailto:`, `tel:`, `http(s)://`, `#`) fall back to a
 * native `<a>` (Next `<Link>` is for in-app routes only). Ref feedback 2026-07-17
 * "clicking a row = router.push, not router.replace, even if it's a link".
 *
 * Shared by {@link SurfaceListCardRow} and {@link SurfaceListCardItem} ΓÇö each hands
 * in its own `dataComponent` so the rendered anchor still carries that caller's own
 * identity rather than a generic one.
 */
/** Props for {@link RowAnchor}. */
interface RowAnchorProps {
    href: string
    onClick?: () => void
    className?: string
    dataComponent: string
    children: React.ReactNode
}

const RowAnchor = ({
    href,
    onClick,
    className,
    dataComponent,
    children,
}: RowAnchorProps) => {
    if (href.startsWith("/")) {
        return (
            <Link href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
                {children}
            </Link>
        )
    }
    return (
        <a href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
            {children}
        </a>
    )
}

/**
 * Props for {@link SurfaceListCard}.
 *
 * Legacy children API ΓÇö migrate to `SurfaceCardListProps` (`items`,
 * `SurfaceLabelProps`, `emptyState` / `error` / `errorState`, `description`,
 * `isSkeleton`, `identity`). B37 Decision F: keep the inherited `className`
 * door until every consumer is migrated; do not widen it.
 */
export interface SurfaceListCardProps extends WithClassNames<undefined> {
    /** The rows ({@link SurfaceListCardRow}) of the joined list. */
    children: React.ReactNode
    /**
     * Renders `border border-default` instead of `shadow-surface` ΓÇö for when
     * this list sits NESTED inside another surface (a modal/drawer body),
     * where `--surface-shadow` can render invisible against the parent surface
     * (dark mode) ΓÇö nested cards need a border to delineate (`components/card.md`
     * ┬º"surface-in-surface / nested" ΓÇö KEEP border, do NOT convert to shadow).
     * Defaults to `false` (existing top-level usages keep the shadow look).
     * Prefer `variant="nested"` on `SurfaceCardList` for new call sites.
     */
    bordered?: boolean
    /**
     * Set when a sentence-tier component roots on this card: it then emits THAT
     * component's identity instead of its own, so the caller never wraps itself in an
     * identity div (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * @deprecated B37 legacy shell ΓÇö prefer `SurfaceCardList`
 * (`composites/cards/SurfaceCard` `.List`). Kept compilable for remaining
 * children-based call sites; do not add new consumers.
 *
 * Bounded SURFACE list card: one `bg-surface` container with a border + large
 * radius, holding {@link SurfaceListCardRow}s edge-to-edge (the `Accordion
 * variant="surface"` skin ΓÇö NOT a real accordion). Each row owns the FULL-BLEED
 * separator + hover; the last row hides its separator automatically (reviewer,
 * 2026-07-14: "surface-in-surface gets a full-width separator too") ΓÇö full-bleed
 * everywhere, no inset-vs-nested split).
 *
 * Use for a list of clickable items that should read as ONE card (foundation
 * categories/resources, payment methodsΓÇª), not N separate cards. Style lives
 * here (block); features only feed rows. Ref `elements/card.md` ┬º3c.
 *
 * REUSE NOTE: `composites/cards/SurfaceCard`'s `.List` member is the newer,
 * DATA-driven (`items`) sibling of this exact shape (its own header even says
 * "was `SurfaceListCard` + its two rows"). This folder keeps the original
 * children-based API on purpose ΓÇö call sites still compose it with JSX rows
 * today, and moving them to `items` is a call-site migration outside this
 * pass's scope, not a rewrite this file can make alone.
 *
 * B37 Decision F: the public `className` door stays until consumers are gone ΓÇö
 * burn it only at zero remaining live users. Do not add further CSS doors.
 *
 * @param props - {@link SurfaceListCardProps}
 * @see Story: .storybook/stories/blocks/cards/SurfaceListCard/SurfaceListCard.stories
 */
export const SurfaceListCard = ({ children, bordered = false, className, identity }: SurfaceListCardProps) => (
    <div
        className={cn(
            "overflow-hidden rounded-3xl bg-surface",
            bordered ? "border border-default" : "shadow-surface",
            className,
        )}
        {...resolveIdentity(identity, { tier: "composite", name: "SurfaceListCard" })}
    >
        {children}
    </div>
)

/** Props for {@link SurfaceListCardRow}. */
export interface SurfaceListCardRowProps extends WithClassNames<undefined> {
    /** Optional leading slot (thumbnail/icon), kept at intrinsic size ΓÇö a buildable slot. */
    leading?: ComponentType
    /** Primary line ΓÇö medium foreground, single-line truncate. */
    title: string
    /** Optional secondary line ΓÇö muted, smaller, single-line truncate. */
    subtitle?: string
    /** Optional right-aligned metadata slot (chips/counts) before the trailing slot ΓÇö a buildable slot. */
    meta?: ComponentType
    /** Optional far-right slot (caret / inline action) ΓÇö a buildable slot. */
    trailing?: ComponentType
    /** Press handler ΓåÆ renders an interactive `<button>` row. */
    onPress?: () => void
    /** Link target ΓåÆ renders an `<a>` row that navigates on click. */
    href?: string
    /** Tints the row as the active selection. */
    selected?: boolean
    /** Disables the row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment. `"fill"` (default) tints the whole row (`bg-default`) ΓÇö for
     * card-like rows / bounded objects. `"underline"` is link-style: the TITLE
     * underlines on hover with NO row fill ΓÇö for a list whose title IS the link
     * (e.g. a most-read list). Ref `interactive-needs-hover` (row-as-link ΓåÆ underline
     * the label, don't colour the whole block).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict band: an inset colored PILL on the left marking this row with a signal
     * that comes from DATA (`card.md` ┬º3i) ΓÇö e.g. a keyword's popularity tier. See
     * {@link VerdictBand} (same shape as `SurfaceListCardItem.withVerdict`).
     */
    withVerdict?: VerdictBand
}

/**
 * One row of a {@link SurfaceListCard}, laying out leading ┬╖ title+subtitle ┬╖
 * meta+trailing (the same slot shape as `ListRow`, surface-card skin) with a
 * full-bleed inset separator auto-hidden on the last row. STATIC by default (a
 * plain `<div>`, NO hover/focus/cursor); pass `onPress`/`href` to make the whole
 * row a tappable `<button>`/`<a>` with `hover:bg-default` + focus ring. A static
 * row never fakes interactivity with a hover tint (`hover-style-matches-clickable-nature`).
 *
 * The row's OWN frame (separator, hover fill, focus ring, verdict band) is a shape
 * decision this composite owns directly (`cn`) ΓÇö no frame carries an `after:`
 * pseudo-element separator or a data-driven inset shadow. The row's INTERIOR ΓÇö
 * leading ┬╖ title/subtitle ┬╖ meta/trailing ΓÇö is assembled from `Typography` inside
 * `Box`/`StackH` frames wherever a frame can express it exactly (title/subtitle
 * keeps a literal `gap-0` column, one step tighter than `Stack`'s narrowest `gap={1}`
 * step, so it stays a plain flex column).
 *
 * @param props - {@link SurfaceListCardRowProps}
 */
export const SurfaceListCardRow = ({
    leading: Leading,
    title,
    subtitle,
    meta: Meta,
    trailing: Trailing,
    onPress,
    href,
    selected = false,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
}: SurfaceListCardRowProps) => {
    // a row is only interactive when it actually does something; a STATIC row must
    // not fake interactivity with a hover tint / focus ring / button semantics
    // (`hover-style-matches-clickable-nature` ΓÇö mirrors SurfaceListCardItem).
    const interactive = Boolean(onPress || href)
    const underlineHover = hover === "underline"
    const rowClassName = cn(
        "relative flex w-full items-center gap-3 p-3 text-left",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        // hover + focus + cursor ONLY when interactive. link-style rows form a hover
        // `group` (the title underlines) with no fill; card-style rows tint the row
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        interactive && (underlineHover ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        "disabled:cursor-not-allowed disabled:opacity-60",
        selected && "bg-accent-soft",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        className,
    )

    const content = (
        <>
            {Leading ? <div className="shrink-0"><Leading /></div> : null}
            {/* Deliberately NOT `StackV`: the closest step on the frame's gap scale is
                `gap={1}` (0.25rem) and this column needs a true `gap-0` ΓÇö the two text
                lines are meant to sit with no seam between them (missing vocabulary: the
                frame has no zero step, see `_spacing.ts` `AllowedGap`). */}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography size="sm" truncate underlineOnGroupHover={underlineHover} text={title} />
                {subtitle ? <Typography size="xs" color="muted" truncate text={subtitle} /> : null}
            </div>
            {Meta || Trailing ? (
                <Box principle="push-end" className="ml-auto shrink-0"
                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                    <StackH gap={2} items={[() => (Meta ? <Meta /> : null), () => (Trailing ? <Trailing /> : null)]} />
                </Box>
            ) : null}
        </>
    )

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={rowClassName} dataComponent="SurfaceListCardRow">
                {content}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={rowClassName}
                data-tier="composite"
                data-component="SurfaceListCardRow"
            >
                {content}
            </button>
        )
    }
    // static row (no onPress/href) ΓÇö a plain div: no button semantics, no hover
    return (
        <div className={rowClassName} data-tier="composite" data-component="SurfaceListCardRow">
            {content}
        </div>
    )
}

/** Props for {@link SurfaceListCardItem}. */
export interface SurfaceListCardItemProps extends WithClassNames<undefined> {
    /** Arbitrary row content (the block owns padding + the inset separator). */
    children: React.ReactNode
    /** Press handler ΓåÆ renders an interactive `<button>` row (hover + focus ring). */
    onPress?: () => void
    /** Link target ΓåÆ renders an `<a>` row that navigates on click. */
    href?: string
    /** Disables the interactive row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment for an interactive row. `"fill"` (default) tints the whole
     * row (`bg-default`) ΓÇö the accordion-skin hover, for SELECT/expand rows that
     * keep you on the surface (e.g. payment methods). `"underline"` makes the row a
     * hover `group` with NO fill ΓÇö for a NAV row whose title is a link (navigates
     * away); the feature adds `group-hover:underline` to its title. Ref
     * `hover-style-matches-clickable-nature` (go-there ΓåÆ underline, stay-here ΓåÆ fill).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this row with a signal that
     * comes from DATA (`card.md` ┬º3i) ΓÇö e.g. the league's promote/demote zone. See
     * {@link VerdictBand} (same shape as `SectionCard.withVerdict`).
     */
    withVerdict?: VerdictBand
    /**
     * Caller identity to wear on this item's root instead of its own ΓÇö pass this
     * when a sentence-tier component roots on this item (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * One free-form row of a {@link SurfaceListCard} ΓÇö bespoke content (not the fixed
 * leading/title/subtitle slots of {@link SurfaceListCardRow}). The block owns the
 * row padding + inset bottom separator (auto-hidden on the last row); the feature
 * lays out whatever it needs inside (e.g. a changelog entry, or a course row with a
 * progress bar). STATIC by default; pass `onPress`/`href` to make the WHOLE row a
 * tappable `<button>`/`<a>`. `hover="fill"` (default) tints the row (accordion skin);
 * `hover="underline"` is link-style (the row is a `group`, no fill ΓÇö the feature
 * underlines its own title). Ref `elements/card.md` ┬º3b/┬º3c.
 *
 * @param props - {@link SurfaceListCardItemProps}
 */
export const SurfaceListCardItem = ({
    children,
    onPress,
    href,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
    identity,
}: SurfaceListCardItemProps) => {
    const interactive = Boolean(onPress || href)
    const itemClassName = cn(
        "relative block w-full p-3 text-left",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        // link-style rows form a hover `group` (the title underlines) with NO fill;
        // select/expand rows tint the whole row (accordion skin)
        interactive && (hover === "underline" ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "SurfaceListCardItem" })

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={itemClassName} dataComponent="SurfaceListCardItem">
                {children}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={itemClassName}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }
    return (
        <div className={itemClassName} {...identityAttrs}>
            {children}
        </div>
    )
}

import React from "react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"

/**
 * `PhaseScarcityNote` ΓÇö the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/**
 * Props for {@link _PhaseScarcityNote}. The two sentences are REQUIRED unless
 * `isSkeleton` (┬º12b) ΓÇö the price preview hasn't arrived yet, so there is no
 * honest phase/seat fact to state. They arrive already localized: the phase name
 * and the interpolated copy are the connected half's to resolve.
 */
export type PhaseScarcityNoteBaseProps =
    | { isSkeleton: true; seatsRemaining?: number | null; slotsLeftLabel?: string | null; priceRisingLabel?: string | null }
    | {
        isSkeleton?: false
        /** Seats left at this phase's price; `null` = unlimited ΓåÆ renders NOTHING. */
        seatsRemaining: number | null
        /** "N seats left at the X price", already localized. */
        slotsLeftLabel: string | null
        /** "price rises to Y after that", already localized; `null` = no rise to mention. */
        priceRisingLabel: string | null
    }

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) ΓÇö an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` ΓÇö this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const _PhaseScarcityNote = ({
    seatsRemaining,
    slotsLeftLabel,
    priceRisingLabel,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <Typography size="sm" isSkeleton />
    }
    // no seat cap at this phase ΓåÆ no honest scarcity reason ΓåÆ stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` ΓÇö the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ΓçÆ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `┬╖` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // ┬º5a: icon matches the FONT-SIZE of the text beside it ΓÇö `sm`
                        // (14px) ΓçÆ `size-3.5`. ┬º5.0a: below `size-5` ΓçÆ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={slotsLeftLabel}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) ΓÇö but they're still TWO SEPARATE cluster items, since the
                    // `┬╖` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(priceRisingLabel != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={priceRisingLabel}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

export { _PhaseScarcityNote }

