import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for {@link TierCardBase} (shared shell for {@link TierCard} and {@link FreeTierCard}). */
export interface TierCardBaseProps extends WithClassNames<undefined> {
    /**
     * Tier level icon ΓÇö a BUILDABLE slot (uncalled component), never a built element:
     * an element handed in is already rendered, so this shell cannot decide not to.
     */
    icon: ComponentType
    /** Tier display name ΓÇö text, so it arrives as text. */
    title: string
    /** Optional adornment rendered after the title (e.g. the "popular" chip). */
    badge?: ComponentType
    /** Short tagline shown in a fixed `h-[2lh]` slot so cards align. */
    description?: string
    /** Price block ΓÇö a buildable slot; the tiers lay their price out differently. */
    price: ComponentType
    /** Feature rows shown in the footer, each rendered with a seal-check icon. */
    features: string[]
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** Call-to-action rendered in place of the "current plan" badge ΓÇö a buildable slot. */
    cta: ComponentType
    /**
     * First load, nothing in hand ΓåÆ every content slot shimmers while the card keeps
     * its own boxes, so the grid does not jump on resolve. The resting shape lives
     * HERE, in the file that owns it: three hand-mirrored twins used to describe this
     * same card and could drift from it independently.
     */
    isSkeleton?: boolean
    /**
     * Caller identity to wear on this shell's root instead of its own ΓÇö pass this
     * when a sentence-tier card roots on this base (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/** How many feature rows the resting card shows ΓÇö the paid tiers all list two. */
const SKELETON_FEATURE_ROWS = 2

/**
 * Shared shell for an AI subscription tier card (paid or free).
 *
 * Presentational only: renders the icon+title row, fixed-height description,
 * price block, current-plan badge vs CTA, and the feature list footer.
 * Callers ({@link TierCard}, {@link FreeTierCard}) supply tier-specific
 * content (icon, price layout, CTA) and keep their own business logic.
 * @param props - shell content for one tier card
 */
export const TierCardBase = ({
    icon: Icon,
    title,
    badge: Badge,
    description,
    price: Price,
    features,
    isCurrent,
    cta: Cta,
    className,
    isSkeleton = false,
    identity,
}: TierCardBaseProps) => {
    const t = useTranslations()
    // resting rows stand in for whatever the caller would have listed
    const featureRows = isSkeleton
        ? Array.from({ length: SKELETON_FEATURE_ROWS }, (_row, index) => index)
        : features.map((_feature, index) => index)

    return (
        <Card
            className={cn("flex h-full flex-col", className)}
            {...resolveIdentity(identity, { tier: "composite", name: "TierCardBase" })}
        >
            <Card.Content className="flex flex-1 flex-col gap-3">
                {/* icon + tier name (+ optional badge) ΓÇö tight pair */}
                <div className="flex items-center gap-2">
                    {isSkeleton
                        ? <Skeleton className="size-6 shrink-0 rounded-full" />
                        : <Icon />}
                    <Typography type="h5" weight="semibold">
                        {isSkeleton ? <Skeleton className="h-5 w-16 rounded" /> : title}
                    </Typography>
                    {isSkeleton || !Badge ? null : <Badge />}
                </div>
                {/* short tagline ΓÇö fixed slot so cards align */}
                <div className="h-[2lh]">
                    <Typography type="body-sm" color="muted" className="line-clamp-3">
                        {isSkeleton ? <Skeleton className="h-4 w-3/4 rounded" /> : (description ?? "")}
                    </Typography>
                </div>
                <div className="flex flex-col gap-2">
                    {isSkeleton ? <Skeleton className="h-9 w-24 rounded" /> : <Price />}
                </div>
                {isSkeleton ? (
                    <Skeleton className="h-10 w-full rounded-3xl" />
                ) : isCurrent ? (
                    <div className="flex w-full items-center justify-center rounded-3xl bg-success-soft px-3 py-2">
                        <Typography type="body-sm" weight="medium" className="text-success-soft-foreground">
                            {t("aiSubscription.currentPlan")}
                        </Typography>
                    </div>
                ) : <Cta />}
            </Card.Content>
            <Card.Footer>
                {/* feature list ΓÇö seal-check icon + muted text */}
                <div className="flex flex-col gap-2">
                    {featureRows.map((index) => (
                        <div key={index} className="flex items-center gap-2">
                            {isSkeleton
                                ? <Skeleton className="size-5 shrink-0 rounded" />
                                : (
                                    <SealCheckIcon
                                        aria-hidden
                                        className="size-5 shrink-0 text-muted"
                                    />
                                )}
                            <Typography type="body-sm" color="muted">
                                {isSkeleton
                                    ? <Skeleton className="h-4 w-40 max-w-full rounded" />
                                    : features[index]}
                            </Typography>
                        </div>
                    ))}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, {
    useEffect,
    useState,
} from "react"

/** Brand + celebratory palette for the falling pieces. */
const COLORS = ["#d6006e", "#eab308", "#16a34a", "#3b82f6", "#f97316", "#a855f7"]

/** Props for {@link Confetti}. */
export interface ConfettiProps {
    /**
     * Bump this to fire a burst (e.g. a counter incremented on a win). `0` stays
     * idle; each distinct non-zero value fires exactly one burst.
     */
    fireKey: number
    /** Piece count (default 90). */
    count?: number
}

/** One falling piece's randomised layout. */
interface Piece {
    id: string
    left: number
    delay: number
    duration: number
    color: string
    width: number
    rotate: number
}

/**
 * A lightweight, dependency-free confetti burst ΓÇö a fixed, non-interactive overlay
 * that rains coloured pieces down the viewport once per `fireKey` change, then
 * clears itself. Pure CSS fall animation (no canvas, no library). Used to celebrate
 * a top-3 league finish when the viewer lands on a board where they've placed.
 *
 * @param props - {@link ConfettiProps}
 */
export const Confetti = ({
    fireKey,
    count = 90,
}: ConfettiProps) => {
    const [pieces, setPieces] = useState<Array<Piece>>([])

    useEffect(
        () => {
            if (!fireKey) {
                return
            }
            // randomise in the effect (client-only) so there is no SSR hydration drift
            const next: Array<Piece> = []
            for (let i = 0; i < count; i += 1) {
                next.push({
                    id: `${fireKey}-${i}`,
                    left: Math.random() * 100,
                    delay: Math.random() * 0.4,
                    duration: 2 + Math.random() * 1.5,
                    color: COLORS[i % COLORS.length],
                    width: 6 + Math.random() * 6,
                    rotate: Math.random() * 360,
                })
            }
            setPieces(next)
            const timer = window.setTimeout(() => setPieces([]), 4000)
            return () => window.clearTimeout(timer)
        },
        [fireKey, count],
    )

    if (pieces.length === 0) {
        return null
    }

    return (
        <div aria-hidden className="pointer-events-none fixed inset-0 z-50 overflow-hidden">
            <style>
                {"@keyframes starci-confetti-fall{0%{transform:translateY(-12vh) rotate(0deg);opacity:1}100%{transform:translateY(112vh) rotate(720deg);opacity:.85}}"}
            </style>
            {pieces.map((piece) => (
                <span
                    key={piece.id}
                    className="absolute top-0 rounded-[2px]"
                    style={{
                        left: `${piece.left}%`,
                        width: `${piece.width}px`,
                        height: `${piece.width * 0.6}px`,
                        backgroundColor: piece.color,
                        animation: `starci-confetti-fall ${piece.duration}s linear ${piece.delay}s forwards`,
                    }}
                />
            ))}
        </div>
    )
}

"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { VerdictBand } from "@/components/blocks/cards/verdict-band"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { UserCell } from "@/components/composites/lists/UserCell"
import {
    placeMedalIcon,
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import { StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One normalised leaderboard row (the container maps its query data into this). */
export interface LeaderboardRow {
    /** React key + stable id. */
    key: string
    /** 1-based rank ΓÇö Γëñ3 renders a place medal, else the number. */
    rank: number
    /** Display username (null ΓåÆ dash). */
    username: string | null
    /** Avatar URL (null ΓåÆ generated fallback). */
    avatar?: string | null
    /** Pre-formatted trailing value (e.g. "640 pts" / "1420 XP"). */
    valueLabel: React.ReactNode
    /** True ΓåÆ highlight as the viewer (accent value + `meLabel` suffix). */
    isMe?: boolean
    /** Profile link target; omit ΓåÆ the identity is non-clickable. */
    profileHref?: string
    /** Context action at the far right (rank-delta caret / follow button). */
    trailing?: React.ReactNode
    /**
     * Optional left band (`SurfaceListCardItem.withVerdict`, `card.md` ┬º3i) ΓÇö a DATA
     * signal on this row (e.g. the weekly cohort's promote/demote zone). Pass the
     * canonical {@link VerdictBand} (`variant`/`color`) ΓÇö NOT a free-form `className`,
     * which `verdictBandClassName` silently ignores (was the "invisible border" bug).
     */
    verdict?: VerdictBand
}

/** The viewer's own standing shown as the card's header line. */
export interface LeaderboardStanding {
    /** Viewer's rank ΓÇö drives the leading {@link IconTile} badge (medal Γëñ3 / cup 4+). */
    rank: number
    /** Primary line (e.g. "Rank #1 ┬╖ top 20%"). */
    primary: React.ReactNode
    /** Secondary muted line (e.g. "640 pts ┬╖ Resets in 1 day 18 hours"). */
    secondary?: React.ReactNode
}

/** Props for {@link LeaderboardListCard}. */
export interface LeaderboardListCardProps extends WithClassNames<undefined> {
    /**
     * Bare mode ΓÇö skip the {@link LabeledCard} frame (`title`/`onSeeMore` ignored) and
     * render just the standing + list. For a full page that already has its own
     * `PageHeader` (the course leaderboard); the dashboard cards leave it off.
     */
    bare?: boolean
    /** Card label (LabeledCard heading). Ignored when `bare`. */
    title?: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label. */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). */
    standing?: LeaderboardStanding
    /**
     * Optional node between the standing and the list ΓÇö e.g. a `Podium` on a spacious
     * page (course leaderboard). Dashboard cards omit it (compact, no podium).
     */
    topSlot?: React.ReactNode
    /** The ranked rows (top-N slice; when a podium is in `topSlot`, pass rank 4+). */
    rows: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    /** "You" suffix appended to the viewer's own row name. */
    meLabel?: React.ReactNode
}

/**
 * The ONE shared render for a dashboard leaderboard preview ΓÇö a {@link LabeledCard}
 * with the viewer's own standing (rank-driven {@link IconTile} badge: medal for the
 * podium, cup below) over a bordered {@link SurfaceListCard} of ranked rows (top-3
 * wear place medals). Both the weekly "Weekly league" and the global "Top learners"
 * cards map their data into this, so they render IDENTICALLY (teacher 2026-07-17 "2
 * identical sections"); only the per-context `trailing` slot (rank-delta caret vs follow)
 * and the emergent badge differ. Presentational + props-only; containers own the fetch.
 *
 * @param props - {@link LeaderboardListCardProps}
 */
export const LeaderboardListCard = ({
    bare = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    topSlot,
    rows,
    selfRow,
    ellipsisLabel,
    meLabel,
    className,
}: LeaderboardListCardProps) => {
    /** Render one row (shared by the ranked list and the pinned self-row). */
    const renderRow = (row: LeaderboardRow) => {
        const displayName = row.isMe && row.username && meLabel
            ? `${row.username} ┬╖ ${meLabel}`
            : (row.username ?? "")
        const identity = (
            <UserCell
                username={displayName}
                avatar={row.avatar ?? undefined}
                isOwnRow={row.isMe }
            />
        )
        return (
            <SurfaceListCardItem key={row.key} withVerdict={row.verdict}>
                <div className="flex items-center gap-3">
                    {/* top-3 ΓåÆ place medal (≡ƒÑç≡ƒÑê≡ƒÑë); rank 4+ ΓåÆ plain number. Number matches the
                        medal's w-6 CENTERED slot (teacher 2026-07-17 "4 and 5 still misaligned") at the same
                        text-sm foreground as the name (same-row same-size, `visual-hierarchy`). */}
                    {row.rank <= 3 ? (
                        <span className="flex w-6 shrink-0 items-center justify-center">
                            {placeMedalIcon(row.rank)}
                        </span>
                    ) : (
                        <span className="flex w-6 shrink-0 items-center justify-center text-sm text-foreground">
                            {row.rank}
                        </span>
                    )}
                    {row.profileHref ? (
                        <Link
                            href={row.profileHref}
                            className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                        >
                            {identity}
                        </Link>
                    ) : (
                        <div className="flex min-w-0 flex-1 items-center">{identity}</div>
                    )}
                    {/* value = meta ΓåÆ always muted + right-aligned tabular so the XP column
                        lines up across rows (teacher 2026-07-17: accent moves to the NAME, value
                        stays muted). */}
                    <Typography
                        type="body-sm"
                        color="muted"
                        className="shrink-0 text-right tabular-nums"
                    >
                        {row.valueLabel}
                    </Typography>
                    {row.trailing ? (
                        <div className="flex shrink-0 items-center">{row.trailing}</div>
                    ) : null}
                </div>
            </SurfaceListCardItem>
        )
    }

    const contentItems = [
        ...(standing
            ? [() => (
                <div className="flex items-center gap-3">
                    <IconTile icon={rankBadgeIcon(standing.rank)} tone="neutral" size="sm" />
                    <div className="flex min-w-0 flex-col">
                        <Typography type="body-sm" weight="bold" truncate>
                            {standing.primary}
                        </Typography>
                        {standing.secondary ? (
                            <Typography type="body-xs" color="muted">
                                {standing.secondary}
                            </Typography>
                        ) : null}
                    </div>
                </div>
            )]
            : []),
        ...(topSlot ? [() => <>{topSlot}</>] : []),
        ...(rows.length > 0 || selfRow
            ? [() => (
                <SurfaceListCard bordered>
                    {rows.map(renderRow)}
                    {selfRow ? (
                        <>
                            <SurfaceListCardItem>
                                <div className="flex min-h-8 items-center gap-3">
                                    <span className="flex w-6 shrink-0 items-center justify-center text-base leading-none tracking-widest text-muted">
                                        Γï»
                                    </span>
                                    <Typography type="body-sm" color="muted">
                                        {ellipsisLabel}
                                    </Typography>
                                </div>
                            </SurfaceListCardItem>
                            {renderRow(selfRow)}
                        </>
                    ) : null}
                </SurfaceListCard>
            )]
            : []),
    ]

    // bare ΓåÆ the page owns the frame (PageHeader); dashboard cards keep the LabeledCard
    if (bare) {
        return (
            <div className={cn("flex flex-col gap-3", className)}>
                {contentItems.map((Item, index) => (
                    <Item key={index} />
                ))}
            </div>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "LeaderboardListCard" }}
            // `title` is only ever omitted in `bare` mode, which already returned above ΓÇö
            // the fallback here is a type-safety guard, not a real state either caller hits.
            label={title ?? ""}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
        >
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Standing, optional podium, and cohort list are peer sections in one leaderboard ΓÇö not block-boundary, because they stay inside one card group."
                items={contentItems}
            />
        </LabeledCard>
    )
}

