import React from "react"
import {
    BookOpenIcon,
    CardsIcon,
    CodeIcon,
    FlagIcon,
    FlameIcon,
    PuzzlePieceIcon,
    type Icon as PhosphorIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StatGridCard, type StatGridCardItem } from "@/components/composites/stats/StatGridCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { GlyphMark } from "@/components/atoms/display/GlyphMark"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `WeeklyGoals`: "Weekly Goals" ΓÇö the composite summary + six-metric
 * breakdown. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 * ≡ƒôÉ LEAF by STRUCTURE (┬º14d.2): the six metrics never change the SHAPE of the
 * tree, only the numbers inside it, so this block has exactly ONE leaf
 * ("Content") ΓÇö loading / error / content are states of that one leaf, the
 * same shape `ChallengeScoreCard`'s single leaf uses. No `isEmpty` state:
 * `items` is always the fixed six-metric set (see the component file header).
 */

/** The six weekly metrics this block always renders, in display order (mirrors backend `KpiKey`). */
export type WeeklyGoalKey = "lessons" | "studyDays" | "challenges" | "coding" | "flashcards" | "milestones"

/** One weekly-goal metric: current-week value vs the effective target, plus its coin reward. */
export interface WeeklyGoalItem {
    /** Which metric this row is. */
    key: WeeklyGoalKey
    /** Already-localized metric name (e.g. "Lessons") ΓÇö screen copy, not owned by this block. */
    label: string
    /** The current-week value. */
    current: number
    /** The learner's custom weekly target; `null` when none set (the block falls back to a sensible default). */
    target: number | null
    /** Coin reward for claiming this metric this week; `null` when no target is set server-side. */
    coinReward: number | null
    /** `true` ΓåÆ this metric's reward can be claimed right now (met + not yet claimed). */
    canClaim: boolean
}

/** The viewer's weekly-goals snapshot (real shape of `myKpis`). */
export interface WeeklyGoalsData {
    /** All six metrics, in display order. */
    items: Array<WeeklyGoalItem>
    /** Server-computed composite score across every metric ΓÇö read straight, never recomputed. */
    composite: {
        /** Average completion across the six metrics, 0ΓÇô100. */
        percent: number
        /** Number of metrics already met (current >= effective target). */
        completed: number
        /** Always 6 ΓÇö the fixed metric count. */
        total: number
    }
    /** Already-worded countdown to the weekly reset (e.g. "3 days 12 hours left"). Omit while unknown. */
    resetInLabel?: string
}

/** Props for {@link WeeklyGoals}. */
export interface WeeklyGoalsProps {
    /** True while the first load is running ΓÇö {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** Truthy ΓåÆ the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The viewer's weekly-goals snapshot. Required once loaded (no error). */
    data?: WeeklyGoalsData
    /** Sensible default target per metric, used when a metric has no custom `target` set yet. */
    defaultTargets: Record<WeeklyGoalKey, number>
    /** `true` ΓåÆ every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** Phosphor icon per metric key ΓÇö a pure display constant, decoupled from any editor's own map. */
const KPI_ICON: Record<WeeklyGoalKey, PhosphorIcon> = {
    lessons: BookOpenIcon,
    studyDays: FlameIcon,
    challenges: PuzzlePieceIcon,
    coding: CodeIcon,
    flashcards: CardsIcon,
    milestones: FlagIcon,
}

/** One metric cell's content: icon + label + ratio row, then the meter, then an optional coin hint. */
const goalCellContent = (
    item: WeeklyGoalItem,
    defaultTargets: Record<WeeklyGoalKey, number>,
    isSkeleton: boolean,
) => {
    const Icon = KPI_ICON[item.key]
    const effectiveTarget = item.target ?? defaultTargets[item.key]

    const iconLabel = (
        <StackH gap={2} isSkeleton={isSkeleton} items={[
            () => (
                <GlyphMark
                    icon={Icon}
                    tone="muted"
                    isSkeleton={isSkeleton}
                />
            ),
            () => (
                <Typography
                    size="sm"
                    isSkeleton={isSkeleton}
                    text={item.label}

                />
            ),
        ]} />
    )

    const labelRow = (
        <StackH gap={3} principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            justify="between" isSkeleton={isSkeleton} items={[
                () => iconLabel,
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `${item.current}/${effectiveTarget}`}

                    />
                ),
            ]} />
    )

    return (
        <StackV gap={3} isSkeleton={isSkeleton} items={[
            () => labelRow,
            () => (
                <ProgressMeter
                    value={item.current}
                    max={effectiveTarget > 0 ? effectiveTarget : 1}
                    isSkeleton={isSkeleton}
                />
            ),
            ...(!isSkeleton && item.coinReward != null ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent" : "muted"}
                    isSkeleton={isSkeleton}
                    text={`+${item.coinReward} coins when met`}

                />
            )] : []),
        ]} />
    )
}

/** Fixed-shape placeholder rendered while {@link WeeklyGoalsProps.isLoading} ΓÇö six empty cells, no real data yet. */
const loadingItems = (defaultTargets: Record<WeeklyGoalKey, number>): Array<WeeklyGoalItem> =>
    (Object.keys(defaultTargets) as Array<WeeklyGoalKey>).map((key) => ({
        key,
        label: "",
        current: 0,
        target: null,
        coinReward: null,
        canClaim: false,
    }))

/** Props for the internal {@link Content} tree ΓÇö reused for both the real render and the loading skeleton. */
interface ContentProps {
    items: Array<WeeklyGoalItem>
    composite: WeeklyGoalsData["composite"]
    resetInLabel?: string
    defaultTargets: Record<WeeklyGoalKey, number>
    isSkeleton: boolean
}

const Content = ({ items, composite, resetInLabel, defaultTargets, isSkeleton }: ContentProps) => {
    const summary = isSkeleton
        ? undefined
        : `${composite.percent}% complete (${composite.completed}/${composite.total} goals)${resetInLabel != null ? ` ┬╖ ${resetInLabel}` : ""}`
    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => goalCellContent(item, defaultTargets, isSkeleton),
    }))
    return (
        <StackV
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because the summary and metric grid are repeating siblings in one card."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        isSkeleton={isSkeleton}
                        text={summary}
                    />
                ),
                () => <StatGridCard items={gridItems} />,
            ]}
        />
    )
}

/**
 * "Weekly Goals" ΓÇö the weekly-goal summary + six-metric breakdown. See the
 * file header for the full contract.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
const WeeklyGoals = ({
    isLoading,
    error,
    onRetry,
    data,
    defaultTargets,
    isSkeleton = false,
}: WeeklyGoalsProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyGoals" }}
        label="Weekly Goals"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Content
                        items={loadingItems(defaultTargets)}
                        composite={{ percent: 0, completed: 0, total: 6 }}
                        defaultTargets={defaultTargets}
                        isSkeleton

                    />
                )}
                error={error}
                errorContent={{
                    title: "Couldn't load weekly goals",
                    description: "Retry to see the latest progress.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content
                        items={data.items}
                        composite={data.composite}
                        resetInLabel={data.resetInLabel}
                        defaultTargets={defaultTargets}
                        isSkeleton={isSkeleton}

                    />
                ) : null)}
            />
        )}
    />
)

export { WeeklyGoals }

"use client"

import React, { useEffect, useState } from "react"

/**
 * Thin top-of-viewport reading-progress bar (0ΓåÆ100% of document scroll). Posts
 * run ~2000 words, so a lightweight progress signal helps orientation. Purely
 * presentational; listens to window scroll and paints an accent fill.
 */
export const ReadingProgress = () => {
    const [progress, setProgress] = useState(0)

    useEffect(() => {
        const update = () => {
            const scrollable = document.documentElement.scrollHeight - window.innerHeight
            const ratio = scrollable > 0 ? window.scrollY / scrollable : 0
            setProgress(Math.min(1, Math.max(0, ratio)))
        }
        update()
        window.addEventListener("scroll", update, { passive: true })
        window.addEventListener("resize", update)
        return () => {
            window.removeEventListener("scroll", update)
            window.removeEventListener("resize", update)
        }
    }, [])

    return (
        <div
            className="fixed top-0 left-0 right-[var(--app-rail-w,0px)] z-50 h-0.5 bg-transparent"
            role="progressbar"
            aria-label="Reading progress"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress * 100)}
        >
            <div
                className="h-full bg-accent transition-[width] duration-150 ease-out"
                style={{ width: `${progress * 100}%` }}
            />
        </div>
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { PostRow } from "@/components/blocks/blog/PostRow"
import { StackV } from "@/components/frames/Stack"
import { queryBlogPosts } from "@/modules/api/graphql/queries/query-blog-posts"
import { BlogCategory } from "@/modules/api/graphql/queries/types/blog"

/** How many related posts to surface at most. */
const MAX_RELATED = 3

/** Props for {@link RelatedPosts}. */
export interface RelatedPostsProps {
    /** Pillar to pull related posts from (the current article's category). */
    category: BlogCategory
    /** Slug of the current article ΓÇö excluded from the related list. */
    currentSlug: string
}

/**
 * "More in {pillar}" strip at the end of an article. Reuses the existing
 * `blogPosts(category)` query (no new backend) to keep readers in the same
 * editorial pillar. Self-hiding: renders nothing when there are no other posts.
 */
export const RelatedPosts = ({ category, currentSlug }: RelatedPostsProps) => {
    const t = useTranslations("blog")
    const locale = useLocale()

    const { data } = useSWR(
        ["blog-related", category, currentSlug],
        async () => {
            const response = await queryBlogPosts({
                request: { category, limit: MAX_RELATED + 1, offset: 0 },
            })
            return response.data?.blogPosts.data ?? []
        },
    )

    const related = (data ?? [])
        .filter((post) => post.slug !== currentSlug)
        .slice(0, MAX_RELATED)

    // self-hiding section ΓÇö nothing to show when this is the only post in the pillar
    if (related.length === 0) {
        return null
    }

    const formatDate = (iso: string) =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    return (
        <section className="border-t border-default pt-6">
            <StackV
                principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <h2 className="text-lg font-semibold text-foreground">
                            {t("relatedTitle", { category: t(`categories.${category}`) })}
                        </h2>
                    ),
                    ...related.map((post) => () => (
                        <PostRow
                            post={post}
                            formattedDate={formatDate(post.publishedAt)}
                        />
                    )),
                ]}
            />
        </section>
    )
}

