/**
 * Public `/blog/[slug]` article ΓÇö the presentational half of {@link BlogPostPage}. Renders a reading-progress
 * bar (once real content is showing), a persistent "back to blog" link, and ΓÇö error ΓåÆ not-found ΓåÆ content,
 * in that fixed priority ΓÇö the serif header, the markdown body, the members-only gate, the GitHub source +
 * funnel CTAs, and a "More in {pillar}" strip. The content region threads `isSkeleton` to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md); `MarkdownContent` has no `isSkeleton` of its
 * own, so its slot swaps to a co-located `Skeleton.Paragraph` mirror while shimmering instead.
 *
 * @param props - {@link BlogPostPageProps}
 */
export const _BlogPostPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    title,
    category,
    categoryTone = "default",
    isPremium = false,
    coverImageUrl,
    body,
    isLocked = false,
    sourceUrl,
    ctaUrl,
    slug,
    labels,
}: BlogPostPageProps) => {
    // Always-visible chrome ΓÇö present in every branch (error/not-found/content alike), unlike the
    // async region below it.
