"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { HeadhuntingCompanyBreadcrumbs } from "./HeadhuntingCompanyBreadcrumbs"
import { HeadhuntingCompanyConsultants } from "./HeadhuntingCompanyConsultants"
import { HeadhuntingCompanyProfile } from "./HeadhuntingCompanyProfile"
import { HeadhuntingCompanyLoadingState } from "./HeadhuntingCompanyLoadingState"
import { useHeadhuntingCompanyDetail } from "@/hooks/headhunting"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link HeadhuntingCompanyPage}. */
export type HeadhuntingCompanyPageProps = Record<string, never>
/**
 * Headhunting company detail: company profile and the consultants at that company.
 * Container ΓÇö owns data + breadcrumb orchestration via hooks; renders presentational children.
 * @param props - {@link HeadhuntingCompanyPageProps}
 */
export const HeadhuntingCompanyPage = () => {
    const t = useTranslations()
    const {
        companyId,
        company,
        companies,
        error,
        retry,
    } = useHeadhuntingCompanyDetail()

    // an errored query never lands in Redux, so `companies` stays undefined ΓÇö the
    // loading gate below would otherwise spin forever; surface a retry instead
    if (error && !companies) {
        return (
            <AsyncContentError
                title={t("headhuntings.error")}
                onRetry={retry}
                retryLabel={t("common.retry")}
            />
        )
    }

    if (!companies) {
        return <HeadhuntingCompanyLoadingState />
    }

    if (!company && companyId) {
        return (
            <div>
                <Typography type="body-sm" color="muted">{t("headhuntings.companyNotFound")}</Typography>
            </div>
        )
    }

    return (
        <Box>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    HeadhuntingCompanyBreadcrumbs,
                    HeadhuntingCompanyProfile,
                    HeadhuntingCompanyConsultants,
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useState,
} from "react"
import { Button, Chip, Link, Typography, Spinner } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    FaGithub,
} from "react-icons/fa6"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    EntityToken,
} from "@/components/blocks/entity/EntityToken"
import { useQueryMyChallengeSubmissionsSwr, MY_CHALLENGE_SUBMISSIONS_LIMIT } from "@/hooks/swr/api/graphql/queries/useQueryMyChallengeSubmissionsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link MySubmissionsPage}. */
export type MySubmissionsPageProps = Record<string, never>
/** Map a submission status to a HeroUI Chip color. */
const STATUS_COLOR_MAP: Record<string, "success" | "danger" | "warning"> = {
    passed: "success",
    failed: "danger",
    pending: "warning",
}

/**
 * The learner's challenge submissions as a list ΓÇö title, course, status chip,
 * score, language, repo link and date. "Load more" grows the page window via a
 * single offset=0 query (`myChallengeSubmissions`).
 *
 * @param props - optional root className.
 */
export const MySubmissionsPage = () => {
    const t = useTranslations()
    const locale = useLocale()

    /** How many pages have been requested (drives the growing window). */
    const [pageCount, setPageCount] = useState(1)

    const swr = useQueryMyChallengeSubmissionsSwr(
        0,
        MY_CHALLENGE_SUBMISSIONS_LIMIT * pageCount,
    )
    const items = swr.data?.items ?? []
    const total = swr.data?.total ?? 0
    const hasMore = items.length < total

    const formatDate = (iso: string): string =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    const listItems = [
        () => (
            <div className="flex flex-col gap-0">
                {items.map((item, index) => (
                    <ListRow
                        key={item.id}
                        title={item.challengeTitle}
                        divider={index < items.length - 1}
                        meta={(
                            <>
                                <EntityToken
                                    globalId={item.courseGlobalId}
                                    label={item.courseTitle}
                                />
                                <Chip
                                    size="sm"
                                    variant="soft"
                                    color={STATUS_COLOR_MAP[item.status] ?? "warning"}
                                >
                                    <Chip.Label>
                                        {t(`profileSettings.learning.submissions.status.${item.status}`)}
                                    </Chip.Label>
                                </Chip>
                                <Typography type="body-sm">
                                    {item.score}
                                </Typography>
                                <Typography type="body-xs" color="muted">
                                    {item.selectedLang ?? "ΓÇö"}
                                </Typography>
                                <Typography type="body-xs" color="muted">
                                    {formatDate(item.submittedAt)}
                                </Typography>
                            </>
                        )}
                        trailing={item.submissionUrl ? (
                            <Link
                                href={item.submissionUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-accent-soft-foreground"
                            >
                                <StackH
                                    inline
                                    gap={3}
                                    align="center"
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    items={[
                                        () => <FaGithub aria-hidden focusable="false" className="size-5" />,
                                        () => <>{t("profileSettings.learning.submissions.open")}</>,
                                    ]}
                                />
                            </Link>
                        ) : (
                            <Typography type="body-xs" color="muted">ΓÇö</Typography>
                        )}
                    />
                ))}
            </div>
        ),
        ...(hasMore
            ? [() => (
                <div className="flex justify-center">
                    <Button
                        variant="ghost"
                        size="sm"
                        isDisabled={swr.isValidating}
                        onPress={() => setPageCount((count) => count + 1)}
                    >
                        {swr.isValidating ? (
                            <Spinner color="current" size="sm" />
                        ) : null}
                        {t("profileSettings.learning.loadMore")}
                    </Button>
                </div>
            )]
            : []),
    ]

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.submissions.title")} />}
                title={t("profileSettings.learning.submissions.title")}
                description={t("profileSettings.learning.submissions.subtitle")}
            />

            <SurfaceCard
                label={t("profileSettings.learning.submissions.title")}

                body={() => (
                    <AsyncContent
                        isLoading={!swr.data && !swr.error}
                        skeleton={(
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[0, 1, 2].map((row) => () => (
                                    <Skeleton.ListRow key={row} withTrailing />
                                ))}
                            />
                        )}
                        isEmpty={items.length === 0}
                        emptyContent={{
                            title: t("profileSettings.learning.submissions.empty"),
                            description: t("profileSettings.learning.submissions.emptyHint"),
                        }}
                        error={!swr.data ? swr.error : undefined}
                        errorContent={{
                            title: t("profileSettings.learning.submissions.empty"),
                            onRetry: () => { void swr.mutate() },
                            retryLabel: t("profileSettings.learning.loadMore"),
                        }}
                    >
                        <StackV gap={4} items={listItems} />
                    </AsyncContent>
                )}
            />
        </div>
    )
}

"use client"

import React from "react"
import type { Key } from "react"
import { ChartLineUpIcon, RocketLaunchIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { GroupPressableCard, type GroupPressableCardItem } from "@/components/blocks/cards/GroupPressableCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Container } from "@/components/frames/Container"
import type { UserJobReadinessBand } from "@/modules/api/graphql/queries/types/user-job-readiness"

/** Number of placeholder cards shown while the candidate list first loads. */
const SKELETON_COUNT = 6

/** Maps a readiness band to the `Chip` tone that reads correctly. */
const bandToneOf = (band: UserJobReadinessBand): "success" | "warning" | "default" =>
    band === "jobReady" ? "success" : band === "building" ? "warning" : "default"

/** One selectable track (course) in the filter strip. */
export interface TalentDirectoryTrack {
    /** Course id ΓÇö also the SWR/tab selection key. */
    key: string
    /** Course title, already resolved for the current locale. */
    label: string
}

/** One recruiter-facing candidate card, already resolved (identity + the FILTERED-track badge). */
export interface TalentDirectoryCandidate {
    /** Stable React key ΓÇö the candidate's user id. */
    key: string
    /** Profile link, already built for the current locale. */
    href: string
    /** Display name, already falling back to the username when blank. */
    displayName: string
    /** Role title, already falling back to `@username` when blank. */
    roleTitle: string
    avatar?: string | null
    /** Seed for the generated fallback avatar (falls back to the username). */
    seed?: string | null
    /** Qualitative badge ΓÇö track-specific, never a blended cross-track score. */
    isQualified: boolean
    band: UserJobReadinessBand
    bio?: string | null
}

/** All display text, already localized by the connected `TalentDirectoryPage`; a story passes i18n keys. */
export interface TalentDirectoryLabels {
    title: string
    description: string
    trackFilterAria: string
    candidatesAria: string
    emptyTitle: string
    emptyDescription: string
    errorTitle: string
    retry: string
    qualified: string
    /** Readiness-band chip label, keyed by {@link UserJobReadinessBand}. */
    band: Record<UserJobReadinessBand, string>
}

/** Props for {@link _TalentDirectoryPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface TalentDirectoryPageProps {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero candidates for the selected track ΓåÆ the empty message. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ΓÇö paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The tracks a recruiter can filter on. The strip stays hidden until at least one resolves AND a track is selected. */
    tracks: Array<TalentDirectoryTrack>
    /** Currently selected track id. `null` before the first course resolves. */
    selectedTrackKey: string | null
    /** Fired with the newly selected track's id ΓÇö re-keys the ranked candidate query. */
    onSelectTrack: (key: string) => void
    /** Ranked candidates for the selected track, in display order. */
    candidates: Array<TalentDirectoryCandidate>
    labels: TalentDirectoryLabels
}

/**
 * Recruiter marketplace ΓÇö pick ONE track (course) and browse the open-to-work
 * candidates for it, ranked by that track's depth (strongest first). The
 * presentational half of {@link TalentDirectoryPage} (`design/storybook/architecture/
 * split.md`): four states in the fixed order error ΓåÆ skeleton ΓåÆ empty ΓåÆ content,
 * `error` falling to the shared `AsyncContentError` frame and `isEmpty` to
 * `AsyncContentEmpty`, otherwise the one real tree renders with `isSkeleton`
 * threaded to every leaf that supports it so the shimmer mirrors the loaded shape
 * (`loading-and-skeleton.md`). Each card shows the candidate's identity plus the
 * qualitative `band`/`isQualified` badge for the FILTERED track ONLY: never a
 * blended cross-track score, never a raw meaningless number (the fair-monetization
 * model ΓÇö see `.workflows/00-INDEX.md`).
 *
 * @param props - {@link TalentDirectoryPageProps}
 */
export const _TalentDirectoryPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    tracks,
    selectedTrackKey,
    onSelectTrack,
    candidates,
    labels,
}: TalentDirectoryPageProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8). Kept
    // inside the same `max-w-5xl`/`p-6` measure (`Container size="lg"`) the
    // content renders in below, so the page chrome doesn't jump between states.
    if (error) {
        return (
            <Container
                identity={{ tier: "block", component: "TalentDirectoryPage" }}
                size="lg"
                padding={6}
                body={() => (
                    <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
                )}
            />
        )
    }
    if (!isSkeleton && isEmpty) {
        return (
            <Container
                identity={{ tier: "block", component: "TalentDirectoryPage" }}
                size="lg"
                padding={6}
                body={() => (
                    <AsyncContentEmpty
                        icon={ChartLineUpIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                    />
                )}
            />
        )
    }

    // ROW shape ΓÇö while shimmering, placeholder cards keep the SAME `GroupPressableCard`
    // shape (row component + count) as the loaded grid. `UserAvatar` has no `isSkeleton`
    // of its own (block, not atom/composite), so it is mirrored in place with `Skeleton.Avatar`
    // right where it sits ΓÇö still co-located, not a parallel tree.
    const candidateItems: Array<GroupPressableCardItem> = isSkeleton
        ? Array.from({ length: SKELETON_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            isDisabled: true,
            content: () => (
                <StackV gap={3} items={[
                    () => (
                        <StackH gap={3} items={[
                            () => <Skeleton.Avatar size="lg" />,
                            () => (
                                <StackV gap={1} classNames={["min-w-0"]} items={[
                                    () => <Typography size="sm" weight="semibold" isSkeleton />,
                                    () => <Typography size="xs" color="muted" isSkeleton />,
                                ]} />
                            ),
                        ]} />
                    ),
                    () => <StackH gap={2} items={[() => <Chip isSkeleton />]} />,
                ]} />
            ),
        }))
        : candidates.map((candidate) => ({
            key: candidate.key,
            href: candidate.href,
            content: () => (
                <StackV gap={3} items={[
                    () => (
                        <StackH gap={3} items={[
                            () => (
                                <UserAvatar
                                    username={candidate.displayName}
                                    avatar={candidate.avatar}
                                    seed={candidate.seed}
                                    className="size-12"
                                />
                            ),
                            () => (
                                <StackV gap={1} classNames={["min-w-0"]} items={[
                                    () => <Typography size="sm" weight="semibold" truncate text={candidate.displayName} />,
                                    () => <Typography size="xs" color="muted" truncate text={candidate.roleTitle} />,
                                ]} />
                            ),
                        ]} />
                    ),
                    // qualitative track badges ONLY ΓÇö no blended score, no raw number
                    () => (
                        <StackH gap={2} items={[
                            ...(candidate.isQualified ? [() => (
                                <Chip tone="success" icon={RocketLaunchIcon} text={labels.qualified} />
                            )] : []),
                            () => <Chip tone={bandToneOf(candidate.band)} text={labels.band[candidate.band]} />,
                        ]} />
                    ),
                    ...(candidate.bio?.trim() ? [() => (
                        <Typography size="xs" color="muted" lineClamp={2} text={candidate.bio ?? ""} />
                    )] : []),
                ]} />
            ),
        }))

    const onSelectionChange = (key: Key) => onSelectTrack(String(key))

    return (
        <Container
            identity={{ tier: "block", component: "TalentDirectoryPage" }}
            size="lg"
            padding={6}
            isSkeleton={isSkeleton}
            body={() => (
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => <PageHeader title={labels.title} description={labels.description} />,

                        // track filter (single-select nav ΓåÆ underline tabs). Changing the track
                        // re-keys the candidate query below ΓåÆ server-side re-rank. Hidden until
                        // tracks resolve + a selection exists ΓÇö same condition as before, and it
                        // never coincides with the skeleton grid below (both wait on the same
                        // course fetch), so no separate skeleton mirror is needed here.
                        ...(tracks.length > 0 && selectedTrackKey ? [() => (
                            <TabsCard
                                leftTabs={{
                                    items: tracks.map((track) => ({ key: track.key, label: track.label })),
                                    selectedKey: selectedTrackKey,
                                    ariaLabel: labels.trackFilterAria,
                                    onSelectionChange,
                                }}
                            />
                        )] : []),

                        () => (
                            <GroupPressableCard
                                ariaLabel={labels.candidatesAria}
                                // container steps, not viewport. A candidate card carries a 48px
                                // avatar + name + chips, so it needs real width: two-up from 576px
                                // (Γëê284px each), three-up only from 896px (Γëê293px each).
                                columns={{ base: 1, xl: 2, xl4: 3 }}
                                items={candidateItems}
                            />
                        ),
                    ]} />
            )}
        />
    )
}
